  (id,subject_key,year,academic_year,week,session,duration_minutes,sp_code,printed_pages,content_sha256,reviewed_blocks_sha256,approval_manifest_sha256,approval_status,active,lesson,reviewed_blocks,limits)
values
  ('PJ1-2026B-2S-W34-S1','pj',1,2026,34,1,30,'3.2.1',array[50,51]::int[],'cae4bbe09926354748ca55aa5c1c828445c88824f51a1681c113ca932a28d2d4','bd62102fef4ea16b1c0af0adb49dd6c782451aa71f54eb29631628123d4e6bb8','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W34-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 34, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Jantung Kuat, Badan Sihat", "source_title": "Jantung Kuat, Badan Sihat", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T12-R2", "source_row_literal": ["34\n\nKump A: 27.09.2026-01.10.2026\n\nKump B: 28.09.2026- 02.10.2026", "8: CERGAS DAN MANTAP\n\n\nJANTUNG KUAT, BADAN SIHAT", "3.2 Melakukan aktiviti yang meningkatkan kapasiti aerobik.\n4.2 Mengaplikasi konsep asas kapasiti aerobik.\n5.4 Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "3.2.1  Melakukan aktiviti berterusan \ndalam jangka masa yang \nditetapkan.\n\n4.2.1 Menamakan organ utama yang mengepam darah. \n4.2.2 Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.\n4.2.3  Menyatakan senaman yang boleh \nmenguatkanjantung.\n\n5.4.2  Memperlihatkan rasa seronok melakukan aktiviti dalam kumpulan.", "Pemerhatian /\nPentaksiran \n\nPermainan kecil:\nJantungku cergas\n\n\nBT m/s 49-51"], "rpt_original_page_literal": "49-51", "source_pages": [50, 51], "source_pdf_pages": [58, 59], "rpt_book_pages": "50, 51", "main_standard_key": "3.2.1", "sk_code": "3.2", "sk_text": "Melakukan aktiviti yang meningkatkan kapasiti aerobik.", "sp_code": "3.2.1", "sp_text": "Melakukan aktiviti berterusan dalam jangka masa yang ditetapkan.", "complementary_standards": [{"standard_key": "4.2.1", "sp_code": "4.2.1", "sp_text": "Menamakan organ utama yang mengepam darah.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.2", "sp_code": "4.2.2", "sp_text": "Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.3", "sp_code": "4.2.3", "sp_text": "Menyatakan aktiviti yang boleh menguatkan jantung.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Senamrobik setempat dengan langkah mudah", "authoring_focus": "Senamrobik setempat dengan langkah mudah", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Tarian aerobik BT51 serta jalan/larian ringan daripada BT50 disesuaikan dengan ruang sendiri. Tiada papan roda, bangku tinggi atau perlumbaan. Segmen berterusan pendek ditetapkan guru; rehat apabila perlu. Jantung, paru-paru dan contoh aktiviti dijejak untuk setiap murid.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Kon berada di luar tempat langkah dan ayunan tangan. Tiada melompat, berpusing laju atau tendangan tinggi; sentuhan tumit dibuat dekat dengan badan.", "Segmen 1 minit ialah masa latihan ringan, bukan ujian ketahanan maksimum. Murid boleh memperlahankan langkah, berhenti atau berehat; guru mencatat tempoh, bantuan dan sebab berhenti tanpa menghukum keperluan tubuh.", "Murid bernafas seperti biasa. Jika sakit, pening atau sukar bernafas, aktiviti dihentikan dan guru memberi perhatian mengikut tatacara sekolah.", "Guru tidak menyuruh murid mencari nadi sambil bergerak atau menahan nafas. Pelajaran ini tidak memerlukan kiraan denyutan atau sasaran nadi."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Senamrobik setempat: jalan dan sentuh tumit", "objective": "Murid dapat melakukan senamrobik mudah secara berterusan mengikut masa yang ditetapkan guru.", "success_criteria": ["Melakukan rangkaian jalan setempat dan sentuh tumit ke depan selama 1 minit mengikut kemampuan.", "Menamakan jantung dan menyebut hubungan mudah antara paru-paru, oksigen dalam darah dan jantung.", "Menyebut satu aktiviti yang boleh menguatkan jantung jika diamalkan."], "prior_knowledge": "Murid pernah berjalan setempat, mengayun tangan dan berhenti apabila diarahkan.", "equipment": [{"item": "Kon penanda", "quantity": "6 buah", "use": "Empat kon di luar tepi kawasan senamrobik dan dua kon di tepi ruang rehat; tiada kon di tempat murid memijak."}, {"item": "Jam randik", "quantity": "1 buah untuk guru", "use": "Menetapkan segmen bergerak berterusan 1 minit dan tempoh rehat; bukan mengukur usaha maksimum."}, {"item": "Botol air minuman sendiri", "quantity": "1 bagi setiap murid", "use": "Digunakan sebelum, dalam waktu rehat dan selepas aktiviti; diletakkan di tepi kawasan."}, {"item": "Buku teks PJPK Tahun 1", "quantity": "1 naskhah guru, halaman 50–51", "use": "Rujukan tarian aerobik, fungsi jantung dan hubungan dengan paru-paru."}, {"item": "Senarai semak dan pen guru", "quantity": "1 set", "use": "Mencatat tempoh gerakan individu, bantuan, jawapan dan respons dalam kumpulan."}], "preparation": ["Guru memeriksa ruang rata, kering dan bebas halangan. Empat kon diletakkan di luar kawasan pijakan dan dua kon menandakan ruang rehat.", "Tetapkan ruang setiap murid dengan jarak sekurang-kurangnya dua depa. Murid perlu boleh menyentuh tumit ke depan dan mengayun tangan tanpa menghampiri rakan.", "Letakkan botol sendiri di tepi ruang rehat. Guru memeriksa kasut, pakaian dan kesediaan murid; tiada keperluan bangku, bola atau gelung bagi gerakan ini."], "organisation": "Murid bergerak dalam kumpulan kecil tetapi kekal di ruang sendiri. Guru menyusun pasangan A dan B dalam kumpulan untuk semakan: A bergerak pada 20–21 dan 23–24, B pada 21–22 dan 24–25. Murid tanpa pasangan mendapat giliran berhampiran guru. Rakan yang menunggu berehat di ruang sendiri dan memberi galakan tanpa menyentuh. Apabila guru berkata “Berhenti”, hentikan langkah dengan selamat dan pandang guru. Tiada pertandingan antara kumpulan.", "movement_cues": ["Jalan di tempat sendiri. Angkat kaki rendah sahaja.", "Sentuh tumit kanan sedikit ke depan, bawa balik; kemudian tumit kiri. Jangan menendang.", "Ayun tangan perlahan di bawah paras bahu. Terus bernafas seperti biasa.", "Ikut masa guru, bukan kelajuan rakan. Berhenti dan beritahu guru jika tidak selesa."], "timing_note": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 tunjuk cara dan pengenalan organ; 10–19 latihan berselang rehat; 19–26 semakan bergilir; 26–30 penyejukan. Segmen berterusan ditetapkan 1 minit sahaja, diikuti rehat. Guru mengumumkan mula dan tamat, serta mengukur tempoh sebenar jika murid berhenti awal. Peluang minum pada 0–2, 9–10, 12–13, 16–17, 22–23 dan 29–30; rehat tambahan dibenarkan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Jalan di tempat sendiri. Sekarang sentuh tumit ke depan bergilir. Kita bergerak selama satu minit; berhenti lebih awal jika tidak selesa.", "pupils_do": "Murid menyambung langkah kecil dengan sentuhan tumit dan ayunan tangan ringan. Selepas berhenti, murid menjawab soalan guru dengan kata mudah.", "teacher_checks": "Guru melihat gerakan setiap murid sepanjang segmen yang diperhatikan dan mencatat masa sebenar. Guru tidak menganggap kecergasan telah meningkat selepas satu kelas."}, "bbm": ["Kon penanda — 6 buah", "Jam randik — 1 buah untuk guru", "Botol air minuman sendiri — 1 bagi setiap murid", "Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 50–51", "Senarai semak dan pen guru — 1 set", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid bersenam bersama kumpulan kecil dan bergilir menunjukkan rangkaian sendiri. Rakan memberi galakan seperti “ikut langkah kecil” tanpa mendesak murid yang mahu berehat. Semasa rehat, setiap murid menjawab soalan jantung dan paru-paru sendiri; jawapan kumpulan bukan bukti individu.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Minit 0–1: guru memeriksa pakaian, tali kasut, keadaan murid dan permukaan. Guru menunjukkan kawasan senamrobik serta ruang rehat.", "Minit 1–2: guru menetapkan ruang sendiri, mencuba arahan “Berhenti” dan memberi peluang minum sebelum aktiviti."], "pupils": ["Murid memeriksa kasut, membetulkan pakaian dan memberitahu guru jika tidak sihat.", "Murid mengambil ruang tanpa bersentuh, mencuba berhenti mengikut suara guru dan minum jika perlu."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Buku teks PJPK Tahun 1", "Senarai semak dan pen guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru membimbing langkah kecil ke sisi kanan dan kiri tanpa menyilangkan kaki.", "Minit 4–5: guru memimpin ayunan tangan ringan di bawah paras bahu. Minit 5–6: guru membimbing regangan betis kanan dan kiri dengan tumit belakang di lantai serta lutut depan dibengkokkan sedikit."], "pupils": ["Murid berjalan dan melangkah ke sisi dalam ruang sendiri. Murid menjaga jarak dan bernafas seperti biasa.", "Murid mengayun tangan dan meregangkan betis setakat selesa tanpa henjutan. Murid berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Contoh rangkaian dan kenal jantung serta paru-paru", "minutes": 4, "teacher": ["Minit 6–7: guru menunjukkan jalan setempat selama 30 saat, kemudian sentuh tumit kanan dan kiri ke depan bergilir selama 30 saat. Ayunan tangan kekal kecil.", "Minit 7–8: guru memimpin rangkaian yang sama selama 1 minit tanpa hentian di antara dua jenis langkah. Guru menyebut masa mula dan tamat; murid boleh berhenti jika perlu.", "Minit 8–9: semua berhenti dan berehat. Merujuk buku halaman 51, guru menyebut “Jantung mengepam darah. Paru-paru membekalkan oksigen ke dalam darah. Jantung mengepam darah itu ke seluruh badan semasa kita bergerak.”", "Minit 9–10: beri rehat minum. Guru menjelaskan tarian aerobik ialah contoh aktiviti yang boleh menguatkan jantung jika diamalkan; bukan bukti jantung terus menjadi kuat hari ini."], "pupils": ["Murid meniru jalan setempat, kemudian menyentuh tumit sedikit ke depan bergilir. Murid tidak menendang atau keluar dari ruang sendiri.", "Murid mengikuti rangkaian 1 minit dengan nafas biasa; jika perlu, murid berhenti dan memberitahu guru.", "Ketika berhenti, murid mendengar penerangan organ dan mencuba menyebut dua ayat pendek tentang paru-paru serta jantung. Murid minum pada waktu rehat."], "check": "Guru memastikan murid tahu dua gerakan dan arahan mula/tamat. Jawapan beramai-ramai ialah latihan; bukti 4.2.1 dan 4.2.2 hanya daripada murid yang menjawab sendiri.", "resources": ["Kon penanda", "Jam randik", "Buku teks halaman 50–51", "Botol air minuman sendiri"]}, {"name": "Latihan senamrobik satu minit berselang rehat", "minutes": 9, "teacher": ["Minit 10–11: guru menunjukkan semula pertukaran jalan setempat kepada sentuh tumit. Guru menetapkan setiap segmen selama 1 minit: jalan 30 saat dan sentuh tumit bergilir 30 saat.", "Segmen bergerak ialah 11–12, 13–14, 15–16 dan 17–18. Guru memberi arahan mula/tamat, mengingatkan nafas biasa dan memberi bantuan mengikut keperluan tanpa menambah masa atau kelajuan.", "Rehat ialah 12–13, 14–15, 16–17 dan 18–19. Guru memberi peluang minum dan menyoal individu secara bergilir: nama organ pengepam darah, hubungan paru-paru dengan jantung, kemudian satu contoh aktiviti.", "Guru memerhatikan kumpulan kecil secara bergilir sambil kekal mengawasi semua murid. Catat masa sebenar, bantuan dan rehat bagi murid yang diperhatikan; tanya gerakan yang disukai tanpa memaksa respons seronok."], "pupils": ["Murid melakukan dua gerakan secara bersambung dalam setiap segmen yang disertai. Murid tidak perlu mengira masa sendiri atau mengikut kelajuan rakan.", "Murid memperlahankan langkah atau berhenti jika perlu dan memberitahu guru. Murid yang berehat tidak dikejar untuk menyambung.", "Dalam rehat, murid minum jika perlu dan menjawab guru sendiri: “Jantung”, kemudian hubungan paru-paru, oksigen dalam darah dan jantung dengan bantuan jika perlu.", "Murid memberi galakan sopan kepada rakan. Murid boleh menyebut tarian aerobik sebagai contoh aktiviti dan berkongsi gerakan yang disukai jika mahu."], "check": "3.2.1: tempoh dan kesinambungan gerakan individu. 4.2.1, 4.2.2, 4.2.3: jawapan individu dalam rehat. 5.4.2: kata/isyarat sebenar semasa bersama kumpulan; bantuan dan keperluan rehat direkod.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Giliran A dan B serta semakan individu", "minutes": 7, "teacher": ["Minit 19–20: guru menunjukkan giliran A dan B dalam setiap kumpulan. Setiap murid menunjukkan rangkaian selama 1 minit; rakan menunggu dalam ruang sendiri dan tidak bergerak rapat.", "Minit 20–21: A bergerak; 21–22: B bergerak. Minit 22–23: semua berehat/minum, dan guru mengambil jawapan individu yang belum didengar.", "Minit 23–24: A mendapat peluang kedua; 24–25: B mendapat peluang kedua. Ulangan bukan wajib jika murid memerlukan rehat; guru menggunakan giliran ini untuk melengkapkan pemerhatian, bukan menambah usaha maksimum.", "Minit 25–26: semua berhenti dan berehat. Guru menyemak nama jantung, hubungan dengan paru-paru serta satu aktiviti melalui soalan pendek kepada murid yang belum disemak. Rekod perkara yang belum sempat dilihat atau didengar."], "pupils": ["Murid menunjukkan jalan setempat dan sentuh tumit bergilir pada giliran sendiri. Murid bernafas seperti biasa dan boleh berhenti lebih awal.", "Rakan yang menunggu berehat dan memberi galakan ringkas tanpa mengambil alih gerakan. Murid minum pada waktu rehat jika perlu.", "Murid menjawab guru sendiri tentang jantung, paru-paru dan contoh aktiviti. Pilihan lisan serta contoh semula dibenarkan.", "Murid menyatakan jika mahu berehat atau berkongsi gerakan yang disukai bersama kumpulan. Murid tidak dipaksa memberi jawapan seronok."], "check": "Guru menilai segmen yang dilihat dari mula hingga tamat, bukan mengandaikan semua bergerak seminit. Bukti pengetahuan dan rasa seronok dicatat mengikut murid; jawapan rakan tidak dipindahkan.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Minit 26–27: guru memimpin berjalan perlahan setempat. Minit 27–29: guru membimbing regangan tangan dan betis kanan serta kiri dengan lembut tanpa henjutan.", "Minit 29–30: guru memberi masa minum, menyemak keadaan murid dan bertanya aktiviti yang boleh menguatkan jantung. Guru meminta botol sendiri dikemas; kon dikemas selepas kawasan kosong."], "pupils": ["Murid berjalan perlahan dan meregang mengikut keselesaan sambil bernafas seperti biasa.", "Murid minum jika perlu, memberitahu jika masih tidak selesa dan mengemas botol. Murid yang ditanya menyebut satu aktiviti seperti tarian aerobik."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Menyambung jalan setempat dan sentuhan tumit kecil dengan contoh guru sepanjang segmen satu minit.", "materials": ["Ruang sendiri dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 51 untuk penerangan guru"], "teacher": ["Guru berdiri di hadapan murid dan menamakan gerakan satu demi satu. Guru membuat sentuhan tumit kecil untuk ditiru; murid boleh mengekalkan ayunan tangan semula jadi.", "Guru memberi ayat pendek secara berasingan: “Paru-paru beri oksigen ke dalam darah” dan “Jantung pam darah itu ke seluruh badan”. Guru memberi kata mula dan mendengar jawapan murid sendiri; bantuan diteruskan."], "pupil_steps": ["Selepas pemanasan, ambil ruang sendiri. Ikut guru berjalan setempat dengan langkah kecil dan nafas biasa.", "Dalam segmen 1 minit yang ditetapkan, jalan 30 saat lalu sentuh tumit ke depan bergilir 30 saat. Teruskan gerakan setakat selesa; berhenti dan beritahu guru jika perlu rehat.", "Semasa rehat, minum jika perlu. Jawab sendiri “Jantung mengepam darah”. Dengan bantuan, sebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan; namakan tarian aerobik sebagai contoh aktiviti.", "Pada giliran sendiri, tunjuk rangkaian yang sama dengan contoh guru. Berehat ketika rakan bergerak dan beri galakan jika mahu; kongsi rasa sebenar. Akhiri dengan penyejukan dan minum mengikut keperluan."], "product": "Segmen gerakan individu yang diperhatikan dari mula hingga tamat atau masa berhenti sebenar; jawapan sendiri tentang jantung, paru-paru dan aktiviti serta respons ketika bersama kumpulan.", "criterion": "Murid mencuba gerakan bersambung bagi tempoh 1 minit yang ditetapkan. Jika berhenti awal, catat tempoh sebenar dan bukti yang belum lengkap. Nama jantung, hubungan kedua-dua organ dan contoh aktiviti disemak secara lisan dengan bantuan.", "next_step": "Kekalkan langkah rendah dan contoh guru sepanjang segmen. Catat keperluan tubuh; beri peluang susulan yang sesuai tanpa menambah masa atau memaksa murid menyambung.", "example": {"teacher": "Ikut langkah kecil cikgu. Selepas rehat, organ apa mengepam darah? Paru-paru memberi apa ke dalam darah?", "pupil": "Murid bergerak mengikut contoh, kemudian menjawab “Jantung. Paru-paru beri oksigen ke dalam darah. Jantung pam darah ke seluruh badan.”"}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melakukan rangkaian jalan setempat dan sentuh tumit secara bersambung sebelum giliran pasangan.", "materials": ["Ruang pasangan dalam kumpulan dengan kon di tepi", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 50–51"], "teacher": ["Guru menunjukkan pertukaran langkah tanpa berhenti lama di antaranya. Guru memberi peringatan sentuhan tumit dekat dengan badan dan ayunan tangan di bawah bahu.", "Guru membantu melalui kata mula untuk jawapan jantung dan paru-paru. Guru bertanya satu soalan pada satu masa semasa rehat dan membenarkan contoh semula."], "pupil_steps": ["Selepas pemanasan, bersedia di ruang sendiri dalam kumpulan. Cuba jalan setempat dan sentuh tumit ke depan bergilir seperti contoh guru.", "Ikut segmen 1 minit: jalan 30 saat diikuti sentuh tumit 30 saat tanpa hentian yang disengajakan. Bernafas biasa; berhenti jika tidak selesa dan maklumkan guru.", "Dalam rehat, minum jika perlu dan jawab sendiri bahawa jantung mengepam darah. Sebut paru-paru membekalkan oksigen ke dalam darah lalu jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti yang boleh menguatkan jantung jika diamalkan.", "Pada giliran A atau B, tunjuk rangkaian sendiri kepada guru. Berehat serta beri galakan kepada rakan ketika menunggu; kongsi gerakan yang disukai jika mahu. Lakukan penyejukan dan minum selepas aktiviti."], "product": "Lakuan bersambung setiap murid dengan tempoh sebenar, jawapan organ dan contoh aktiviti sendiri serta respons dalam kumpulan.", "criterion": "Murid menyambung gerakan sepanjang 1 minit yang ditetapkan apabila mampu. Rehat awal dan bantuan direkod, bukan dianggap lengkap secara automatik. Hubungan paru-paru, oksigen dalam darah dan jantung mesti disebut, bukan nama organ sahaja.", "next_step": "Ulang peralihan langkah dengan contoh lisan. Jika tempoh belum lengkap kerana perlu rehat, jadualkan peluang lain yang sesuai dan teruskan bantuan.", "example": {"teacher": "Selepas tumit kanan, tumit mana pula? Semasa bergerak, bagaimana paru-paru membantu jantung?", "pupil": "Murid menyambung tumit kiri; semasa rehat menjawab “Paru-paru beri oksigen ke dalam darah. Jantung pam darah itu ke seluruh badan.”"}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas ayunan tangan kecil semasa rangkaian senamrobik yang sama, tanpa menambah masa.", "materials": ["Ruang sendiri dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 51"], "teacher": ["Guru menunjukkan ayunan tangan yang santai semasa jalan dan sentuhan tumit. Guru memberi satu maklum balas tentang gerakan terkawal, bukan meminta langkah lebih besar atau laju.", "Guru memberi bantuan lisan untuk nama jantung, bekalan oksigen oleh paru-paru dan aliran darah ke seluruh badan. Guru membenarkan murid melihat contoh langkah semula sepanjang giliran."], "pupil_steps": ["Selepas pemanasan, cuba jalan setempat dan sentuh tumit dalam ruang sendiri. Selaraskan ayunan tangan kecil setakat selesa.", "Lakukan rangkaian 1 minit yang sama: jalan 30 saat dan sentuh tumit bergilir 30 saat. Kekalkan nafas biasa serta jarak; berhenti jika perlu, bukan memaksa diri kerana giliran dicatat.", "Semasa rehat, minum dan sebut sendiri “Jantung mengepam darah”. Nyatakan paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Beri satu contoh aktiviti, iaitu tarian aerobik.", "Tunjukkan rangkaian individu dengan ayunan tangan yang terkawal pada giliran sendiri. Berehat dan memberi galakan sopan kepada kumpulan; kongsi rasa sebenar jika mahu. Ikut penyejukan dan minum selepas aktiviti."], "product": "Segmen individu dengan ayunan tangan terkawal dan tempoh sebenar; jawapan mudah tentang fungsi organ dan aktiviti serta respons kumpulan.", "criterion": "Murid memperkemas kawalan dalam masa 1 minit yang sama. Tiada tambahan kelajuan atau tempoh. Bukti berterusan, nama jantung, hubungan paru-paru-jantung dan contoh aktiviti diperiksa secara individu.", "next_step": "Jika penyelarasan tangan menyukarkan langkah, kembali kepada ayunan semula jadi. Kekalkan bantuan dan hak untuk rehat; pembaikan kecil tidak menjadi ujian baharu.", "example": {"teacher": "Boleh ayun tangan kecil tanpa menghampiri rakan? Aktiviti apa yang boleh menguatkan jantung jika selalu dilakukan?", "pupil": "Murid memperkemas ayunan dan menjawab “Tarian aerobik”, kemudian melengkapkan hubungan paru-paru dan jantung apabila ditanya."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan senamrobik mudah secara berterusan mengikut masa yang ditetapkan guru.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Minit 6–10: tunjuk langkah serta ajar nama jantung dan hubungan paru-paru dengan darah.", "Segmen 11–12, 13–14, 15–16 dan 17–18: guru menumpukan murid berlainan sambil mengawasi semua. Dalam rehat, dengar jawapan individu dan bantu ayat yang belum lengkap.", "Minit 20–21 dan 23–24: semak A; 21–22 dan 24–25: semak B. Giliran kedua mengutamakan murid yang belum diperhatikan, bukan paksaan untuk murid yang perlu rehat.", "Minit 25–30: lengkapkan jawapan yang sempat dan rekod nama/aspek belum diperhatikan. Jangan menanda semua ahli kumpulan menguasai berdasarkan seorang murid."], "individual_check": "Melakukan rangkaian jalan setempat dan sentuh tumit ke depan selama 1 minit mengikut kemampuan.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu menggunakan jam randik dalam segmen 11–12, 13–14, 15–16 atau 17–18; semakan giliran 20–22 dan 23–25.", "evidence": "Gerakan jalan setempat yang disambung dengan sentuh tumit ke depan; guru merekod segmen yang dilihat penuh serta tempoh sebenar jika murid berhenti.", "criterion": "Murid melakukan rangkaian secara berterusan sepanjang 1 minit yang ditetapkan guru. Bantuan contoh dibenarkan. Jika berhenti lebih awal, catat tempoh, keperluan rehat dan bukti yang belum lengkap; jangan menganggap segmen selesai atau menghukum murid.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; segmen mula/tamat: ____; tempoh sebenar: ____; gerakan bersambung: ____.", "Bantuan: ____; berhenti/rehat dan sebab dimaklumkan: ____; perlu peluang susulan: ____."]}, "pbd_complementary": {"4.2.1": {"method": "Soal jawab individu semasa rehat minit 12–13, 18–19, 22–23 atau 25–26.", "evidence": "Murid sendiri menyebut “Jantung” apabila guru bertanya organ yang mengepam darah.", "criterion": "Murid menamakan jantung; menunjuk dada sahaja belum menjadi bukti menamakan. Bantuan kata mula atau pilihan lisan direkod.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; jawapan organ: ____; bantuan: ____; belum dijawab: ____."]}, "4.2.2": {"method": "Soalan pendek kepada individu ketika berhenti pada minit 14–15, 18–19, 22–23 atau 25–26.", "evidence": "Dua bahagian jawapan sendiri: paru-paru membekalkan oksigen ke dalam darah; jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak.", "criterion": "Murid menyebut hubungan kedua-dua organ melalui ayat mudah. Nama organ sahaja tidak mencukupi; contoh semula dan kata mula dibenarkan tanpa memerlukan huraian panjang.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; paru-paru/oksigen ke dalam darah: ____; jantung mengepam darah ke seluruh badan: ____; bantuan: ____."]}, "4.2.3": {"method": "Soal jawab individu semasa rehat minit 16–17, 25–26 atau penutup 29–30.", "evidence": "Satu contoh aktiviti yang disebut murid sendiri, seperti tarian aerobik atau berlari.", "criterion": "Murid menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan. Pelajaran hari ini tidak membuktikan perubahan kecergasan atau kekuatan jantung.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; contoh aktiviti: ____; bantuan: ____; belum diperoleh: ____."]}, "5.4.2": {"method": "Pemerhatian respons individu bersama kumpulan semasa latihan 11–19 dan giliran 20–25; pertanyaan sukarela dalam rehat.", "evidence": "Kata atau isyarat sebenar tentang seronok bersenam bersama rakan, memberi galakan atau mahu mencuba bersama lagi; guru mencatat konteksnya.", "criterion": "Respons seronok dalam kumpulan direkod hanya jika benar-benar dilihat atau didengar. Kerjasama sahaja tidak membuktikan rasa seronok; pendiam, berhenti atau memerlukan bantuan bukan bukti sikap negatif.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; kata/isyarat dan konteks kumpulan: ____; bantuan/keperluan tubuh: ____; belum diperhatikan: ____."]}}, "intervention": ["Gunakan langkah rendah, sentuhan tumit dekat dan ayunan tangan semula jadi. Guru boleh memberi contoh sepanjang segmen; bantuan tidak perlu ditarik untuk pentaksiran.", "Jika murid berhenti awal, rekod tempoh sebenar serta keperluan tubuh. Beri rehat dan peluang lain yang sesuai; jangan melabel ketahanan rendah atau membuat perbandingan murid.", "Untuk jawapan organ, guru membahagikan penerangan kepada dua ayat pendek tentang paru-paru dan jantung. Murid menyebut sendiri dengan bantuan; respons bersama tidak dipindahkan ke rekod individu.", "Catat aspek yang belum sempat diperhatikan. Tindakan susulan berdasarkan bukti sebenar, bukan andaian peningkatan kecergasan dalam satu sesi."], "book_pages_text": "50, 51", "sp_focus": "", "sp_display": "3.2.1", "complementary": [{"standard_key": "4.2.1", "sp_code": "4.2.1", "sp_text": "Menamakan organ utama yang mengepam darah.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.2", "sp_code": "4.2.2", "sp_text": "Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.3", "sp_code": "4.2.3", "sp_text": "Menyatakan aktiviti yang boleh menguatkan jantung.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "052ac266281259b741bfd243262ff05fc8daa4370dfbe4d228526cac70621b98"}'::jsonb,'[{"kind": "title", "text": "Minggu 34 Sesi 1 — Senamrobik setempat: jalan dan sentuh tumit"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W34-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Jantung Kuat, Badan Sihat"}, {"kind": "p", "text": "Aktiviti guru: Senamrobik setempat: jalan dan sentuh tumit"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 50, 51."}, {"kind": "p", "text": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 tunjuk cara dan pengenalan organ; 10–19 latihan berselang rehat; 19–26 semakan bergilir; 26–30 penyejukan. Segmen berterusan ditetapkan 1 minit sahaja, diikuti rehat. Guru mengumumkan mula dan tamat, serta mengukur tempoh sebenar jika murid berhenti awal. Peluang minum pada 0–2, 9–10, 12–13, 16–17, 22–23 dan 29–30; rehat tambahan dibenarkan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.2: Melakukan aktiviti yang meningkatkan kapasiti aerobik."}, {"kind": "p", "text": "SP utama 3.2.1: Melakukan aktiviti berterusan dalam jangka masa yang ditetapkan."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.1: Menamakan organ utama yang mengepam darah."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.2: Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.3: Menyatakan aktiviti yang boleh menguatkan jantung."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.2: Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan senamrobik mudah secara berterusan mengikut masa yang ditetapkan guru."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan rangkaian jalan setempat dan sentuh tumit ke depan selama 1 minit mengikut kemampuan."}, {"kind": "p", "text": "2. Menamakan jantung dan menyebut hubungan mudah antara paru-paru, oksigen dalam darah dan jantung."}, {"kind": "p", "text": "3. Menyebut satu aktiviti yang boleh menguatkan jantung jika diamalkan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah berjalan setempat, mengayun tangan dan berhenti apabila diarahkan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 6 buah"}, {"kind": "p", "text": "Kegunaan: Empat kon di luar tepi kawasan senamrobik dan dua kon di tepi ruang rehat; tiada kon di tempat murid memijak."}, {"kind": "label", "text": "Jam randik"}, {"kind": "p", "text": "Keperluan: 1 buah untuk guru"}, {"kind": "p", "text": "Kegunaan: Menetapkan segmen bergerak berterusan 1 minit dan tempoh rehat; bukan mengukur usaha maksimum."}, {"kind": "label", "text": "Botol air minuman sendiri"}, {"kind": "p", "text": "Keperluan: 1 bagi setiap murid"}, {"kind": "p", "text": "Kegunaan: Digunakan sebelum, dalam waktu rehat dan selepas aktiviti; diletakkan di tepi kawasan."}, {"kind": "label", "text": "Buku teks PJPK Tahun 1"}, {"kind": "p", "text": "Keperluan: 1 naskhah guru, halaman 50–51"}, {"kind": "p", "text": "Kegunaan: Rujukan tarian aerobik, fungsi jantung dan hubungan dengan paru-paru."}, {"kind": "label", "text": "Senarai semak dan pen guru"}, {"kind": "p", "text": "Keperluan: 1 set"}, {"kind": "p", "text": "Kegunaan: Mencatat tempoh gerakan individu, bantuan, jawapan dan respons dalam kumpulan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memeriksa ruang rata, kering dan bebas halangan. Empat kon diletakkan di luar kawasan pijakan dan dua kon menandakan ruang rehat."}, {"kind": "p", "text": "2. Tetapkan ruang setiap murid dengan jarak sekurang-kurangnya dua depa. Murid perlu boleh menyentuh tumit ke depan dan mengayun tangan tanpa menghampiri rakan."}, {"kind": "p", "text": "3. Letakkan botol sendiri di tepi ruang rehat. Guru memeriksa kasut, pakaian dan kesediaan murid; tiada keperluan bangku, bola atau gelung bagi gerakan ini."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "Murid bergerak dalam kumpulan kecil tetapi kekal di ruang sendiri. Guru menyusun pasangan A dan B dalam kumpulan untuk semakan: A bergerak pada 20–21 dan 23–24, B pada 21–22 dan 24–25. Murid tanpa pasangan mendapat giliran berhampiran guru. Rakan yang menunggu berehat di ruang sendiri dan memberi galakan tanpa menyentuh. Apabila guru berkata “Berhenti”, hentikan langkah dengan selamat dan pandang guru. Tiada pertandingan antara kumpulan."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Jalan di tempat sendiri. Angkat kaki rendah sahaja."}, {"kind": "p", "text": "2. Sentuh tumit kanan sedikit ke depan, bawa balik; kemudian tumit kiri. Jangan menendang."}, {"kind": "p", "text": "3. Ayun tangan perlahan di bawah paras bahu. Terus bernafas seperti biasa."}, {"kind": "p", "text": "4. Ikut masa guru, bukan kelajuan rakan. Berhenti dan beritahu guru jika tidak selesa."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 6 buah"}, {"kind": "p", "text": "2. Jam randik — 1 buah untuk guru"}, {"kind": "p", "text": "3. Botol air minuman sendiri — 1 bagi setiap murid"}, {"kind": "p", "text": "4. Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 50–51"}, {"kind": "p", "text": "5. Senarai semak dan pen guru — 1 set"}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid bersenam bersama kumpulan kecil dan bergilir menunjukkan rangkaian sendiri. Rakan memberi galakan seperti “ikut langkah kecil” tanpa mendesak murid yang mahu berehat. Semasa rehat, setiap murid menjawab soalan jantung dan paru-paru sendiri; jawapan kumpulan bukan bukti individu."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Kon berada di luar tempat langkah dan ayunan tangan. Tiada melompat, berpusing laju atau tendangan tinggi; sentuhan tumit dibuat dekat dengan badan."}, {"kind": "p", "text": "5. Segmen 1 minit ialah masa latihan ringan, bukan ujian ketahanan maksimum. Murid boleh memperlahankan langkah, berhenti atau berehat; guru mencatat tempoh, bantuan dan sebab berhenti tanpa menghukum keperluan tubuh."}, {"kind": "p", "text": "6. Murid bernafas seperti biasa. Jika sakit, pening atau sukar bernafas, aktiviti dihentikan dan guru memberi perhatian mengikut tatacara sekolah."}, {"kind": "p", "text": "7. Guru tidak menyuruh murid mencari nadi sambil bergerak atau menahan nafas. Pelajaran ini tidak memerlukan kiraan denyutan atau sasaran nadi."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 0–1: guru memeriksa pakaian, tali kasut, keadaan murid dan permukaan. Guru menunjukkan kawasan senamrobik serta ruang rehat."}, {"kind": "p", "text": "2. Minit 1–2: guru menetapkan ruang sendiri, mencuba arahan “Berhenti” dan memberi peluang minum sebelum aktiviti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memeriksa kasut, membetulkan pakaian dan memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil ruang tanpa bersentuh, mencuba berhenti mengikut suara guru dan minum jika perlu."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Buku teks PJPK Tahun 1 Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru membimbing langkah kecil ke sisi kanan dan kiri tanpa menyilangkan kaki."}, {"kind": "p", "text": "2. Minit 4–5: guru memimpin ayunan tangan ringan di bawah paras bahu. Minit 5–6: guru membimbing regangan betis kanan dan kiri dengan tumit belakang di lantai serta lutut depan dibengkokkan sedikit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan dan melangkah ke sisi dalam ruang sendiri. Murid menjaga jarak dan bernafas seperti biasa."}, {"kind": "p", "text": "2. Murid mengayun tangan dan meregangkan betis setakat selesa tanpa henjutan. Murid berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Contoh rangkaian dan kenal jantung serta paru-paru — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 6–7: guru menunjukkan jalan setempat selama 30 saat, kemudian sentuh tumit kanan dan kiri ke depan bergilir selama 30 saat. Ayunan tangan kekal kecil."}, {"kind": "p", "text": "2. Minit 7–8: guru memimpin rangkaian yang sama selama 1 minit tanpa hentian di antara dua jenis langkah. Guru menyebut masa mula dan tamat; murid boleh berhenti jika perlu."}, {"kind": "p", "text": "3. Minit 8–9: semua berhenti dan berehat. Merujuk buku halaman 51, guru menyebut “Jantung mengepam darah. Paru-paru membekalkan oksigen ke dalam darah. Jantung mengepam darah itu ke seluruh badan semasa kita bergerak.”"}, {"kind": "p", "text": "4. Minit 9–10: beri rehat minum. Guru menjelaskan tarian aerobik ialah contoh aktiviti yang boleh menguatkan jantung jika diamalkan; bukan bukti jantung terus menjadi kuat hari ini."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru jalan setempat, kemudian menyentuh tumit sedikit ke depan bergilir. Murid tidak menendang atau keluar dari ruang sendiri."}, {"kind": "p", "text": "2. Murid mengikuti rangkaian 1 minit dengan nafas biasa; jika perlu, murid berhenti dan memberitahu guru."}, {"kind": "p", "text": "3. Ketika berhenti, murid mendengar penerangan organ dan mencuba menyebut dua ayat pendek tentang paru-paru serta jantung. Murid minum pada waktu rehat."}, {"kind": "p", "text": "Semakan: Guru memastikan murid tahu dua gerakan dan arahan mula/tamat. Jawapan beramai-ramai ialah latihan; bukti 4.2.1 dan 4.2.2 hanya daripada murid yang menjawab sendiri."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Buku teks halaman 50–51 Botol air minuman sendiri"}, {"kind": "h3", "text": "Langkah 4: Latihan senamrobik satu minit berselang rehat — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 10–11: guru menunjukkan semula pertukaran jalan setempat kepada sentuh tumit. Guru menetapkan setiap segmen selama 1 minit: jalan 30 saat dan sentuh tumit bergilir 30 saat."}, {"kind": "p", "text": "2. Segmen bergerak ialah 11–12, 13–14, 15–16 dan 17–18. Guru memberi arahan mula/tamat, mengingatkan nafas biasa dan memberi bantuan mengikut keperluan tanpa menambah masa atau kelajuan."}, {"kind": "p", "text": "3. Rehat ialah 12–13, 14–15, 16–17 dan 18–19. Guru memberi peluang minum dan menyoal individu secara bergilir: nama organ pengepam darah, hubungan paru-paru dengan jantung, kemudian satu contoh aktiviti."}, {"kind": "p", "text": "4. Guru memerhatikan kumpulan kecil secara bergilir sambil kekal mengawasi semua murid. Catat masa sebenar, bantuan dan rehat bagi murid yang diperhatikan; tanya gerakan yang disukai tanpa memaksa respons seronok."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan dua gerakan secara bersambung dalam setiap segmen yang disertai. Murid tidak perlu mengira masa sendiri atau mengikut kelajuan rakan."}, {"kind": "p", "text": "2. Murid memperlahankan langkah atau berhenti jika perlu dan memberitahu guru. Murid yang berehat tidak dikejar untuk menyambung."}, {"kind": "p", "text": "3. Dalam rehat, murid minum jika perlu dan menjawab guru sendiri: “Jantung”, kemudian hubungan paru-paru, oksigen dalam darah dan jantung dengan bantuan jika perlu."}, {"kind": "p", "text": "4. Murid memberi galakan sopan kepada rakan. Murid boleh menyebut tarian aerobik sebagai contoh aktiviti dan berkongsi gerakan yang disukai jika mahu."}, {"kind": "p", "text": "Semakan: 3.2.1: tempoh dan kesinambungan gerakan individu. 4.2.1, 4.2.2, 4.2.3: jawapan individu dalam rehat. 5.4.2: kata/isyarat sebenar semasa bersama kumpulan; bantuan dan keperluan rehat direkod."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 5: Giliran A dan B serta semakan individu — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 19–20: guru menunjukkan giliran A dan B dalam setiap kumpulan. Setiap murid menunjukkan rangkaian selama 1 minit; rakan menunggu dalam ruang sendiri dan tidak bergerak rapat."}, {"kind": "p", "text": "2. Minit 20–21: A bergerak; 21–22: B bergerak. Minit 22–23: semua berehat/minum, dan guru mengambil jawapan individu yang belum didengar."}, {"kind": "p", "text": "3. Minit 23–24: A mendapat peluang kedua; 24–25: B mendapat peluang kedua. Ulangan bukan wajib jika murid memerlukan rehat; guru menggunakan giliran ini untuk melengkapkan pemerhatian, bukan menambah usaha maksimum."}, {"kind": "p", "text": "4. Minit 25–26: semua berhenti dan berehat. Guru menyemak nama jantung, hubungan dengan paru-paru serta satu aktiviti melalui soalan pendek kepada murid yang belum disemak. Rekod perkara yang belum sempat dilihat atau didengar."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjukkan jalan setempat dan sentuh tumit bergilir pada giliran sendiri. Murid bernafas seperti biasa dan boleh berhenti lebih awal."}, {"kind": "p", "text": "2. Rakan yang menunggu berehat dan memberi galakan ringkas tanpa mengambil alih gerakan. Murid minum pada waktu rehat jika perlu."}, {"kind": "p", "text": "3. Murid menjawab guru sendiri tentang jantung, paru-paru dan contoh aktiviti. Pilihan lisan serta contoh semula dibenarkan."}, {"kind": "p", "text": "4. Murid menyatakan jika mahu berehat atau berkongsi gerakan yang disukai bersama kumpulan. Murid tidak dipaksa memberi jawapan seronok."}, {"kind": "p", "text": "Semakan: Guru menilai segmen yang dilihat dari mula hingga tamat, bukan mengandaikan semua bergerak seminit. Bukti pengetahuan dan rasa seronok dicatat mengikut murid; jawapan rakan tidak dipindahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 26–27: guru memimpin berjalan perlahan setempat. Minit 27–29: guru membimbing regangan tangan dan betis kanan serta kiri dengan lembut tanpa henjutan."}, {"kind": "p", "text": "2. Minit 29–30: guru memberi masa minum, menyemak keadaan murid dan bertanya aktiviti yang boleh menguatkan jantung. Guru meminta botol sendiri dikemas; kon dikemas selepas kawasan kosong."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan perlahan dan meregang mengikut keselesaan sambil bernafas seperti biasa."}, {"kind": "p", "text": "2. Murid minum jika perlu, memberitahu jika masih tidak selesa dan mengemas botol. Murid yang ditanya menyebut satu aktiviti seperti tarian aerobik."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Jalan di tempat sendiri. Sekarang sentuh tumit ke depan bergilir. Kita bergerak selama satu minit; berhenti lebih awal jika tidak selesa."}, {"kind": "p", "text": "Murid: Murid menyambung langkah kecil dengan sentuhan tumit dan ayunan tangan ringan. Selepas berhenti, murid menjawab soalan guru dengan kata mudah."}, {"kind": "p", "text": "Semakan guru: Guru melihat gerakan setiap murid sepanjang segmen yang diperhatikan dan mencatat masa sebenar. Guru tidak menganggap kecergasan telah meningkat selepas satu kelas."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W34-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan senamrobik mudah secara berterusan mengikut masa yang ditetapkan guru."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Minit 6–10: tunjuk langkah serta ajar nama jantung dan hubungan paru-paru dengan darah."}, {"kind": "p", "text": "2. Segmen 11–12, 13–14, 15–16 dan 17–18: guru menumpukan murid berlainan sambil mengawasi semua. Dalam rehat, dengar jawapan individu dan bantu ayat yang belum lengkap."}, {"kind": "p", "text": "3. Minit 20–21 dan 23–24: semak A; 21–22 dan 24–25: semak B. Giliran kedua mengutamakan murid yang belum diperhatikan, bukan paksaan untuk murid yang perlu rehat."}, {"kind": "p", "text": "4. Minit 25–30: lengkapkan jawapan yang sempat dan rekod nama/aspek belum diperhatikan. Jangan menanda semua ahli kumpulan menguasai berdasarkan seorang murid."}, {"kind": "p", "text": "Semakan individu: Melakukan rangkaian jalan setempat dan sentuh tumit ke depan selama 1 minit mengikut kemampuan."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Menyambung jalan setempat dan sentuhan tumit kecil dengan contoh guru sepanjang segmen satu minit."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 51 untuk penerangan guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru berdiri di hadapan murid dan menamakan gerakan satu demi satu. Guru membuat sentuhan tumit kecil untuk ditiru; murid boleh mengekalkan ayunan tangan semula jadi."}, {"kind": "p", "text": "2. Guru memberi ayat pendek secara berasingan: “Paru-paru beri oksigen ke dalam darah” dan “Jantung pam darah itu ke seluruh badan”. Guru memberi kata mula dan mendengar jawapan murid sendiri; bantuan diteruskan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Selepas pemanasan, ambil ruang sendiri. Ikut guru berjalan setempat dengan langkah kecil dan nafas biasa."}, {"kind": "p", "text": "2. Dalam segmen 1 minit yang ditetapkan, jalan 30 saat lalu sentuh tumit ke depan bergilir 30 saat. Teruskan gerakan setakat selesa; berhenti dan beritahu guru jika perlu rehat."}, {"kind": "p", "text": "3. Semasa rehat, minum jika perlu. Jawab sendiri “Jantung mengepam darah”. Dengan bantuan, sebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan; namakan tarian aerobik sebagai contoh aktiviti."}, {"kind": "p", "text": "4. Pada giliran sendiri, tunjuk rangkaian yang sama dengan contoh guru. Berehat ketika rakan bergerak dan beri galakan jika mahu; kongsi rasa sebenar. Akhiri dengan penyejukan dan minum mengikut keperluan."}, {"kind": "p", "text": "Contoh guru: Ikut langkah kecil cikgu. Selepas rehat, organ apa mengepam darah? Paru-paru memberi apa ke dalam darah?"}, {"kind": "p", "text": "Contoh respons murid: Murid bergerak mengikut contoh, kemudian menjawab “Jantung. Paru-paru beri oksigen ke dalam darah. Jantung pam darah ke seluruh badan.”"}, {"kind": "p", "text": "Hasil individu: Segmen gerakan individu yang diperhatikan dari mula hingga tamat atau masa berhenti sebenar; jawapan sendiri tentang jantung, paru-paru dan aktiviti serta respons ketika bersama kumpulan."}, {"kind": "p", "text": "Kriteria: Murid mencuba gerakan bersambung bagi tempoh 1 minit yang ditetapkan. Jika berhenti awal, catat tempoh sebenar dan bukti yang belum lengkap. Nama jantung, hubungan kedua-dua organ dan contoh aktiviti disemak secara lisan dengan bantuan."}, {"kind": "p", "text": "Susulan: Kekalkan langkah rendah dan contoh guru sepanjang segmen. Catat keperluan tubuh; beri peluang susulan yang sesuai tanpa menambah masa atau memaksa murid menyambung."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melakukan rangkaian jalan setempat dan sentuh tumit secara bersambung sebelum giliran pasangan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan dalam kumpulan dengan kon di tepi"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 50–51"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan pertukaran langkah tanpa berhenti lama di antaranya. Guru memberi peringatan sentuhan tumit dekat dengan badan dan ayunan tangan di bawah bahu."}, {"kind": "p", "text": "2. Guru membantu melalui kata mula untuk jawapan jantung dan paru-paru. Guru bertanya satu soalan pada satu masa semasa rehat dan membenarkan contoh semula."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Selepas pemanasan, bersedia di ruang sendiri dalam kumpulan. Cuba jalan setempat dan sentuh tumit ke depan bergilir seperti contoh guru."}, {"kind": "p", "text": "2. Ikut segmen 1 minit: jalan 30 saat diikuti sentuh tumit 30 saat tanpa hentian yang disengajakan. Bernafas biasa; berhenti jika tidak selesa dan maklumkan guru."}, {"kind": "p", "text": "3. Dalam rehat, minum jika perlu dan jawab sendiri bahawa jantung mengepam darah. Sebut paru-paru membekalkan oksigen ke dalam darah lalu jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti yang boleh menguatkan jantung jika diamalkan."}, {"kind": "p", "text": "4. Pada giliran A atau B, tunjuk rangkaian sendiri kepada guru. Berehat serta beri galakan kepada rakan ketika menunggu; kongsi gerakan yang disukai jika mahu. Lakukan penyejukan dan minum selepas aktiviti."}, {"kind": "p", "text": "Contoh guru: Selepas tumit kanan, tumit mana pula? Semasa bergerak, bagaimana paru-paru membantu jantung?"}, {"kind": "p", "text": "Contoh respons murid: Murid menyambung tumit kiri; semasa rehat menjawab “Paru-paru beri oksigen ke dalam darah. Jantung pam darah itu ke seluruh badan.”"}, {"kind": "p", "text": "Hasil individu: Lakuan bersambung setiap murid dengan tempoh sebenar, jawapan organ dan contoh aktiviti sendiri serta respons dalam kumpulan."}, {"kind": "p", "text": "Kriteria: Murid menyambung gerakan sepanjang 1 minit yang ditetapkan apabila mampu. Rehat awal dan bantuan direkod, bukan dianggap lengkap secara automatik. Hubungan paru-paru, oksigen dalam darah dan jantung mesti disebut, bukan nama organ sahaja."}, {"kind": "p", "text": "Susulan: Ulang peralihan langkah dengan contoh lisan. Jika tempoh belum lengkap kerana perlu rehat, jadualkan peluang lain yang sesuai dan teruskan bantuan."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas ayunan tangan kecil semasa rangkaian senamrobik yang sama, tanpa menambah masa."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 51"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan ayunan tangan yang santai semasa jalan dan sentuhan tumit. Guru memberi satu maklum balas tentang gerakan terkawal, bukan meminta langkah lebih besar atau laju."}, {"kind": "p", "text": "2. Guru memberi bantuan lisan untuk nama jantung, bekalan oksigen oleh paru-paru dan aliran darah ke seluruh badan. Guru membenarkan murid melihat contoh langkah semula sepanjang giliran."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Selepas pemanasan, cuba jalan setempat dan sentuh tumit dalam ruang sendiri. Selaraskan ayunan tangan kecil setakat selesa."}, {"kind": "p", "text": "2. Lakukan rangkaian 1 minit yang sama: jalan 30 saat dan sentuh tumit bergilir 30 saat. Kekalkan nafas biasa serta jarak; berhenti jika perlu, bukan memaksa diri kerana giliran dicatat."}, {"kind": "p", "text": "3. Semasa rehat, minum dan sebut sendiri “Jantung mengepam darah”. Nyatakan paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Beri satu contoh aktiviti, iaitu tarian aerobik."}, {"kind": "p", "text": "4. Tunjukkan rangkaian individu dengan ayunan tangan yang terkawal pada giliran sendiri. Berehat dan memberi galakan sopan kepada kumpulan; kongsi rasa sebenar jika mahu. Ikut penyejukan dan minum selepas aktiviti."}, {"kind": "p", "text": "Contoh guru: Boleh ayun tangan kecil tanpa menghampiri rakan? Aktiviti apa yang boleh menguatkan jantung jika selalu dilakukan?"}, {"kind": "p", "text": "Contoh respons murid: Murid memperkemas ayunan dan menjawab “Tarian aerobik”, kemudian melengkapkan hubungan paru-paru dan jantung apabila ditanya."}, {"kind": "p", "text": "Hasil individu: Segmen individu dengan ayunan tangan terkawal dan tempoh sebenar; jawapan mudah tentang fungsi organ dan aktiviti serta respons kumpulan."}, {"kind": "p", "text": "Kriteria: Murid memperkemas kawalan dalam masa 1 minit yang sama. Tiada tambahan kelajuan atau tempoh. Bukti berterusan, nama jantung, hubungan paru-paru-jantung dan contoh aktiviti diperiksa secara individu."}, {"kind": "p", "text": "Susulan: Jika penyelarasan tangan menyukarkan langkah, kembali kepada ayunan semula jadi. Kekalkan bantuan dan hak untuk rehat; pembaikan kecil tidak menjadi ujian baharu."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu menggunakan jam randik dalam segmen 11–12, 13–14, 15–16 atau 17–18; semakan giliran 20–22 dan 23–25."}, {"kind": "p", "text": "Bukti: Gerakan jalan setempat yang disambung dengan sentuh tumit ke depan; guru merekod segmen yang dilihat penuh serta tempoh sebenar jika murid berhenti."}, {"kind": "p", "text": "Kriteria: Murid melakukan rangkaian secara berterusan sepanjang 1 minit yang ditetapkan guru. Bantuan contoh dibenarkan. Jika berhenti lebih awal, catat tempoh, keperluan rehat dan bukti yang belum lengkap; jangan menganggap segmen selesai atau menghukum murid."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; segmen mula/tamat: ____; tempoh sebenar: ____; gerakan bersambung: ____."}, {"kind": "p", "text": "2. Bantuan: ____; berhenti/rehat dan sebab dimaklumkan: ____; perlu peluang susulan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu semasa rehat minit 12–13, 18–19, 22–23 atau 25–26."}, {"kind": "p", "text": "Bukti: Murid sendiri menyebut “Jantung” apabila guru bertanya organ yang mengepam darah."}, {"kind": "p", "text": "Kriteria: Murid menamakan jantung; menunjuk dada sahaja belum menjadi bukti menamakan. Bantuan kata mula atau pilihan lisan direkod."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; jawapan organ: ____; bantuan: ____; belum dijawab: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.2"}, {"kind": "p", "text": "Kaedah: Soalan pendek kepada individu ketika berhenti pada minit 14–15, 18–19, 22–23 atau 25–26."}, {"kind": "p", "text": "Bukti: Dua bahagian jawapan sendiri: paru-paru membekalkan oksigen ke dalam darah; jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak."}, {"kind": "p", "text": "Kriteria: Murid menyebut hubungan kedua-dua organ melalui ayat mudah. Nama organ sahaja tidak mencukupi; contoh semula dan kata mula dibenarkan tanpa memerlukan huraian panjang."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; paru-paru/oksigen ke dalam darah: ____; jantung mengepam darah ke seluruh badan: ____; bantuan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.3"}, {"kind": "p", "text": "Kaedah: Soal jawab individu semasa rehat minit 16–17, 25–26 atau penutup 29–30."}, {"kind": "p", "text": "Bukti: Satu contoh aktiviti yang disebut murid sendiri, seperti tarian aerobik atau berlari."}, {"kind": "p", "text": "Kriteria: Murid menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan. Pelajaran hari ini tidak membuktikan perubahan kecergasan atau kekuatan jantung."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; contoh aktiviti: ____; bantuan: ____; belum diperoleh: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons individu bersama kumpulan semasa latihan 11–19 dan giliran 20–25; pertanyaan sukarela dalam rehat."}, {"kind": "p", "text": "Bukti: Kata atau isyarat sebenar tentang seronok bersenam bersama rakan, memberi galakan atau mahu mencuba bersama lagi; guru mencatat konteksnya."}, {"kind": "p", "text": "Kriteria: Respons seronok dalam kumpulan direkod hanya jika benar-benar dilihat atau didengar. Kerjasama sahaja tidak membuktikan rasa seronok; pendiam, berhenti atau memerlukan bantuan bukan bukti sikap negatif."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; kata/isyarat dan konteks kumpulan: ____; bantuan/keperluan tubuh: ____; belum diperhatikan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Gunakan langkah rendah, sentuhan tumit dekat dan ayunan tangan semula jadi. Guru boleh memberi contoh sepanjang segmen; bantuan tidak perlu ditarik untuk pentaksiran."}, {"kind": "p", "text": "2. Jika murid berhenti awal, rekod tempoh sebenar serta keperluan tubuh. Beri rehat dan peluang lain yang sesuai; jangan melabel ketahanan rendah atau membuat perbandingan murid."}, {"kind": "p", "text": "3. Untuk jawapan organ, guru membahagikan penerangan kepada dua ayat pendek tentang paru-paru dan jantung. Murid menyebut sendiri dengan bantuan; respons bersama tidak dipindahkan ke rekod individu."}, {"kind": "p", "text": "4. Catat aspek yang belum sempat diperhatikan. Tindakan susulan berdasarkan bukti sebenar, bukan andaian peningkatan kecergasan dalam satu sesi."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tarian aerobik BT51 serta jalan/larian ringan daripada BT50 disesuaikan dengan ruang sendiri. Tiada papan roda, bangku tinggi atau perlumbaan. Segmen berterusan pendek ditetapkan guru; rehat apabila perlu. Jantung, paru-paru dan contoh aktiviti dijejak untuk setiap murid.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W34-S2','pj',1,2026,34,2,30,'3.2.1',array[50,51]::int[],'1b24af7431d4aa481fe9f13ad8db262fc9a2b8974e159514bf8c341775f2ed38','92b164ee36b2b0ae90323f653ab3115a9605eeda2d5717f7795942b12f527800','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W34-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 34, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Jantung Kuat, Badan Sihat", "source_title": "Jantung Kuat, Badan Sihat", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T12-R2", "source_row_literal": ["34\n\nKump A: 27.09.2026-01.10.2026\n\nKump B: 28.09.2026- 02.10.2026", "8: CERGAS DAN MANTAP\n\n\nJANTUNG KUAT, BADAN SIHAT", "3.2 Melakukan aktiviti yang meningkatkan kapasiti aerobik.\n4.2 Mengaplikasi konsep asas kapasiti aerobik.\n5.4 Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "3.2.1  Melakukan aktiviti berterusan \ndalam jangka masa yang \nditetapkan.\n\n4.2.1 Menamakan organ utama yang mengepam darah. \n4.2.2 Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.\n4.2.3  Menyatakan senaman yang boleh \nmenguatkanjantung.\n\n5.4.2  Memperlihatkan rasa seronok melakukan aktiviti dalam kumpulan.", "Pemerhatian /\nPentaksiran \n\nPermainan kecil:\nJantungku cergas\n\n\nBT m/s 49-51"], "rpt_original_page_literal": "49-51", "source_pages": [50, 51], "source_pdf_pages": [58, 59], "rpt_book_pages": "50, 51", "main_standard_key": "3.2.1", "sk_code": "3.2", "sk_text": "Melakukan aktiviti yang meningkatkan kapasiti aerobik.", "sp_code": "3.2.1", "sp_text": "Melakukan aktiviti berterusan dalam jangka masa yang ditetapkan.", "complementary_standards": [{"standard_key": "4.2.1", "sp_code": "4.2.1", "sp_text": "Menamakan organ utama yang mengepam darah.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.2", "sp_code": "4.2.2", "sp_text": "Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.3", "sp_code": "4.2.3", "sp_text": "Menyatakan aktiviti yang boleh menguatkan jantung.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Rangkaian langkah ke sisi dan jalan cergas", "authoring_focus": "Rangkaian langkah ke sisi dan jalan cergas", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Tarian aerobik BT51 serta jalan/larian ringan daripada BT50 disesuaikan dengan ruang sendiri. Tiada papan roda, bangku tinggi atau perlumbaan. Segmen berterusan pendek ditetapkan guru; rehat apabila perlu. Jantung, paru-paru dan contoh aktiviti dijejak untuk setiap murid.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Langkah ke sisi dibuat kecil tanpa menyilangkan kaki, melompat atau menukar arah secara mengejut. Kon dan botol berada di luar kawasan pijakan.", "Tempoh 2 minit ditetapkan sebagai latihan ringan yang pendek. Murid boleh berhenti lebih awal dan beritahu guru; catat masa sebenar serta keperluan tubuh tanpa hukuman atau perbandingan.", "Guru memastikan murid bernafas seperti biasa. Murid yang sakit, pening atau sukar bernafas dihentikan daripada aktiviti dan diberi perhatian mengikut tatacara sekolah.", "Tiada sasaran nadi, tahan nafas atau ujian maksimum. Rehat, bantuan dan langkah yang lebih kecil dibenarkan sepanjang sesi."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Langkah ke sisi dan jalan berirama", "objective": "Murid dapat menyambung langkah ke sisi dan jalan setempat secara berterusan dalam masa yang ditetapkan guru.", "success_criteria": ["Melakukan rangkaian langkah ke sisi dan jalan setempat selama 2 minit mengikut kemampuan.", "Menamakan jantung serta menyebut hubungan paru-paru, oksigen dalam darah dan jantung.", "Menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan."], "prior_knowledge": "Murid pernah melakukan senamrobik mudah secara bersambung dan berehat selepas segmen pendek.", "equipment": [{"item": "Kon penanda", "quantity": "6 buah", "use": "Empat kon menandakan tepi kawasan langkah ke sisi dan dua kon menandakan ruang rehat; semuanya di luar tempat pijakan."}, {"item": "Jam randik", "quantity": "1 buah untuk guru", "use": "Menandakan rangkaian 2 minit dan waktu rehat; masa berhenti awal dicatat secara sebenar."}, {"item": "Botol air minuman sendiri", "quantity": "1 bagi setiap murid", "use": "Diletakkan di ruang rehat untuk minum sebelum, semasa rehat dan selepas aktiviti."}, {"item": "Buku teks PJPK Tahun 1", "quantity": "1 naskhah guru, halaman 50–51", "use": "Rujukan senamrobik berkumpulan, jantung dan paru-paru."}, {"item": "Senarai semak dan pen guru", "quantity": "1 set", "use": "Merekod langkah individu, tempoh yang dilihat, jawapan dan bantuan."}], "preparation": ["Guru memeriksa permukaan rata, kering dan tidak licin. Semua kon berada di tepi, bukan di laluan kaki.", "Guru menyediakan ruang sendiri dengan jarak sekurang-kurangnya dua depa antara murid. Uji satu langkah kecil ke kanan dan kiri untuk memastikan ruang tidak bertindih.", "Ruang rehat serta botol berada di tepi kawasan dalam pandangan guru. Guru memeriksa pakaian, kasut dan keadaan murid sebelum menetapkan segmen 2 minit yang ringan."], "organisation": "Murid bersenam dalam kumpulan kecil di ruang masing-masing; tiada berjalan mengelilingi kon. Pasangan A dan B dalam kumpulan bergilir untuk semakan: A pada 20–22, B pada 23–25. Rakan menunggu di ruang sendiri sambil berehat. Murid tanpa pasangan menunjukkan gerakan berhampiran guru. Arahan “Berhenti” bermaksud hentikan langkah di tempat selamat dan pandang guru. Murid tidak berlumba, menyilangkan kaki atau masuk ke ruang rakan.", "movement_cues": ["Langkah kecil ke kanan. Rapatkan kaki tanpa bersilang. Ulang ke kiri.", "Apabila cikgu sebut “jalan”, jalan di tempat sendiri sambil mengayun tangan rendah.", "Tukar gerakan dengan tenang. Tidak perlu melompat atau mengangkat lutut tinggi.", "Bernafas seperti biasa. Perlahankan langkah atau berhenti jika tidak selesa."], "timing_note": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 belajar rangkaian; 10–19 latihan dan rehat; 19–26 giliran individu; 26–30 penyejukan. Guru menetapkan segmen 2 minit: langkah ke sisi 30 saat, jalan setempat 30 saat, kemudian ulang urutan sekali. Segmen latihan 11–13 dan 15–17 diselang rehat 13–15 dan 17–19. Semakan A 20–22 dan B 23–25 diselang rehat 22–23. Minum sebelum, pada rehat yang ditetapkan dan selepas; rehat tambahan dibenarkan tanpa memotong penyejukan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Langkah ke kanan dan rapat. Langkah ke kiri dan rapat. Sekarang jalan di tempat sendiri. Kita terus bergerak dengan ringan selama dua minit; kamu boleh berhenti jika perlu.", "pupils_do": "Murid menyambung langkah ke sisi dengan jalan setempat mengikut suara guru. Selepas berhenti, murid menjawab soalan jantung dan paru-paru.", "teacher_checks": "Guru melihat kawalan ruang serta gerakan yang bersambung dan merekod tempoh sebenar. Masa 2 minit bukan ujian usaha maksimum atau bukti kecergasan telah bertambah."}, "bbm": ["Kon penanda — 6 buah", "Jam randik — 1 buah untuk guru", "Botol air minuman sendiri — 1 bagi setiap murid", "Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 50–51", "Senarai semak dan pen guru — 1 set", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid melakukan rangkaian bersama kumpulan kecil dan menyokong giliran A serta B. Rakan memberi satu galakan seperti “langkah kecil” tanpa menyentuh atau mendesak. Semasa rehat, murid berkongsi gerakan yang disukai jika mahu dan setiap orang menjawab soalan organ sendiri.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Minit 0–1: guru memeriksa pakaian, kasut, keadaan murid, permukaan dan kedudukan kon. Guru menunjukkan ruang rehat serta tempat botol.", "Minit 1–2: guru menguji ruang langkah kanan dan kiri, menerangkan arahan “Berhenti” dan memberi peluang minum sebelum aktiviti."], "pupils": ["Murid membetulkan pakaian serta kasut dan memberitahu guru jika tidak sihat. Murid membawa botol sendiri ke ruang rehat.", "Murid mencuba satu langkah kecil ke sisi tanpa menghampiri rakan, kemudian berhenti mengikut suara guru. Murid minum jika perlu."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Buku teks PJPK Tahun 1", "Senarai semak dan pen guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Minit 2–4: guru memimpin berjalan setempat dengan langkah rendah serta ayunan tangan santai, bukan larian.", "Minit 4–5: guru menunjukkan gerakan membuka tangan ke sisi dan merapatkannya dengan lembut. Minit 5–6: guru membimbing regangan betis kanan dan kiri dengan tumit belakang di lantai."], "pupils": ["Murid berjalan di ruang sendiri sambil bernafas seperti biasa dan menjaga jarak.", "Murid menggerakkan tangan serta meregang betis setakat selesa tanpa henjutan. Murid memaklumkan guru jika perlu berehat."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Belajar sambungan sisi dan jalan", "minutes": 4, "teacher": ["Minit 6–7: guru menunjukkan langkah kecil ke kanan, rapatkan kaki, kemudian ke kiri dan rapatkan kaki. Kaki tidak bersilang dan badan kekal menghadap depan.", "Minit 7–8: guru menunjukkan jalan setempat dengan ayunan tangan rendah. Guru mengingatkan murid bergerak dalam ruang sendiri.", "Minit 8–9: guru memimpin contoh rangkaian pendek, iaitu langkah ke sisi 30 saat dan jalan setempat 30 saat tanpa hentian di antaranya. Murid boleh berhenti jika perlu.", "Minit 9–10: semua berehat dan mendapat peluang minum. Guru merujuk buku halaman 51 dan menyebut “Paru-paru membekalkan oksigen ke dalam darah. Jantung mengepam darah itu ke seluruh badan.”"], "pupils": ["Murid meniru langkah ke kanan dan kiri dengan kecil. Murid merapatkan kaki tanpa menyilangkan kaki atau menghampiri rakan.", "Murid menyambung langkah ke sisi dengan jalan setempat apabila mendengar arahan guru. Murid mengayun tangan rendah dan bernafas biasa.", "Murid berhenti dan minum pada waktu rehat. Murid mencuba sebutan “jantung” serta “paru-paru” dengan bimbingan."], "check": "Guru memastikan rangkaian difahami sebelum menambah kepada tempoh 2 minit. Penerangan organ ialah pengajaran awal, bukan keputusan PBD semua murid.", "resources": ["Kon penanda", "Jam randik", "Buku teks halaman 50–51", "Botol air minuman sendiri"]}, {"name": "Rangkaian dua minit dengan rehat", "minutes": 9, "teacher": ["Minit 10–11: ketika murid masih berehat, guru bertanya organ yang mengepam darah. Guru menerangkan dengan ayat pendek bahawa paru-paru memberi oksigen ke dalam darah dan jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak.", "Minit 11–13: guru memimpin langkah ke sisi 30 saat dan jalan setempat 30 saat, kemudian mengulang urutan sekali. Guru menetapkan 2 minit dengan jam randik serta membenarkan berhenti lebih awal.", "Minit 13–15: semua berehat/minum. Guru memberi satu pembetulan mudah pada langkah dan mendapatkan jawapan individu tentang hubungan jantung dengan paru-paru.", "Minit 15–17: ulang rangkaian 2 minit yang sama jika murid selesa. Guru memberi bantuan mengikut keperluan, bukan menambah kelajuan atau jarak.", "Minit 17–19: semua berehat/minum. Guru meminta contoh aktiviti yang boleh menguatkan jantung jika diamalkan, seperti tarian aerobik. Guru bertanya gerakan yang disukai dalam kumpulan tanpa memaksa respons."], "pupils": ["Murid menjawab sendiri tentang jantung ketika berhenti dan mendengar penerangan hubungan dengan paru-paru.", "Murid menyambung langkah ke sisi dan jalan setempat mengikut arahan guru selama tempoh yang ditetapkan, dengan nafas biasa. Murid boleh berhenti lebih awal dan memberitahu guru.", "Dalam rehat, murid minum jika perlu. Murid menjawab dalam dua ayat pendek tentang paru-paru yang memberi oksigen ke dalam darah dan jantung yang mengepam darah itu ke seluruh badan.", "Murid mencuba rangkaian kedua jika selesa dan memberi ruang kepada rakan yang berehat. Selepas berhenti, murid menyebut satu contoh aktiviti dan boleh berkongsi gerakan yang disukai."], "check": "3.2.1: kesinambungan sisi-jalan dan tempoh sebenar setiap murid yang diperhatikan. 4.2.1, 4.2.2, 4.2.3: jawapan sendiri. 5.4.2: respons sebenar ketika bersama kumpulan, bukan andaian kerana murid ikut arahan.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Giliran menunjukkan rangkaian sendiri", "minutes": 7, "teacher": ["Minit 19–20: guru menetapkan A dan B dalam kumpulan. Guru mengulang bahawa setiap giliran ialah 2 minit dan murid boleh berhenti jika perlu.", "Minit 20–22: A melakukan rangkaian sisi-jalan; B berehat di ruang sendiri. Guru memerhatikan murid yang disasarkan sambil memastikan semua kekal dalam pandangan.", "Minit 22–23: semua berehat/minum; guru mengambil jawapan pendek yang belum didengar. Minit 23–25: B menunjukkan rangkaian yang sama dan A berehat.", "Minit 25–26: semua berhenti. Guru bertanya nama organ, hubungan dengan paru-paru atau contoh aktiviti kepada murid yang belum disemak. Guru mencatat aspek yang belum sempat diperhatikan untuk susulan."], "pupils": ["Pada giliran sendiri, murid melakukan langkah ke sisi dan jalan setempat mengikut perubahan arahan guru. Murid tidak menambah kelajuan untuk menarik perhatian.", "Murid yang menunggu berehat di ruang sendiri dan memberi galakan sopan. Murid minum mengikut keperluan serta menghormati rakan yang berhenti awal.", "Selepas berhenti, murid menjawab guru sendiri dengan bantuan jika perlu. Murid boleh menyebut gerakan yang seronok dilakukan bersama kumpulan atau memberitahu jika belum selesa."], "check": "Guru merekod segmen yang dilihat penuh atau masa berhenti sebenar. Bukti kumpulan tidak menggantikan pemerhatian gerakan dan jawapan setiap murid.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Minit 26–27: guru memimpin jalan perlahan setempat. Minit 27–29: guru membimbing regangan tangan dan betis kanan serta kiri yang lembut, tanpa memaksa jarak regangan.", "Minit 29–30: guru memberi masa minum dan memeriksa keadaan murid. Guru mendapatkan jawapan ringkas yang belum diperoleh jika sempat, kemudian mengarahkan botol sendiri dikemas."], "pupils": ["Murid berjalan perlahan, kemudian meregang tangan dan betis sambil bernafas biasa. Murid tidak kembali berlari.", "Murid minum mengikut keperluan, mengemas botol dan memberitahu jika masih tidak selesa. Murid yang ditanya memberi satu jawapan sendiri tentang aktiviti atau organ."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Menyambung langkah ke sisi yang kecil dan jalan setempat sambil meniru guru.", "materials": ["Ruang sendiri dengan kon di tepi", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 51 untuk contoh lisan guru"], "teacher": ["Guru berdiri menghadap arah yang sama berhampiran murid supaya kanan dan kiri mudah diikuti. Guru memberi arahan “sisi, rapat, jalan” satu demi satu; ayunan tangan boleh kekal semula jadi.", "Guru memberi kata mula dan mengulang hubungan paru-paru dengan jantung dalam dua ayat pendek. Guru mendengar jawapan individu dalam rehat serta mencatat bantuan, bukan menjawab bagi pihak murid."], "pupil_steps": ["Sebelum aktiviti, periksa kasut dan ruang dengan bantuan guru serta minum jika perlu. Selepas pemanasan, cuba langkah kecil ke kanan dan kiri tanpa menyilangkan kaki.", "Dalam segmen 2 minit yang ditetapkan, ikut guru melakukan langkah ke sisi 30 saat dan jalan setempat 30 saat, lalu ulang urutan sekali. Bernafas biasa; berhenti dan maklumkan guru jika perlu rehat.", "Semasa rehat, minum dan jawab sendiri “Jantung mengepam darah”. Dengan bantuan, sebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti.", "Pada giliran sendiri, tunjuk rangkaian yang sama dengan contoh guru. Berehat ketika rakan bergerak; beri galakan atau kongsi rasa sebenar jika mahu. Ikut penyejukan, minum selepas dan beritahu keadaan diri."], "product": "Percubaan rangkaian sisi-jalan individu dengan tempoh sebenar, jawapan sendiri tentang kedua-dua organ dan contoh aktiviti serta respons bersama kumpulan.", "criterion": "Guru melihat usaha menyambung gerakan bagi tempoh 2 minit yang ditetapkan. Jika murid berhenti awal, catat masa sebenar dan bukti berterusan yang belum lengkap. Nama jantung, hubungan paru-paru-jantung dan contoh aktiviti dinilai dengan bantuan lisan.", "next_step": "Kekalkan langkah kecil dan contoh berdekatan. Rehat tambahan dibenarkan; susulan diberi mengikut kesediaan tanpa meminta murid mengganti masa yang terlepas.", "example": {"teacher": "Ikut cikgu ke sisi, rapat, kemudian jalan. Selepas rehat, apa yang paru-paru bekalkan ke dalam darah?", "pupil": "Murid meniru rangkaian dan menjawab dengan bantuan “Oksigen. Jantung mengepam darah itu ke seluruh badan.”"}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Menyambung langkah kanan-kiri dan jalan setempat dengan bantuan suara guru.", "materials": ["Ruang pasangan dalam kumpulan dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 50–51"], "teacher": ["Guru menunjukkan kaki dirapatkan tanpa bersilang sebelum langkah ke sisi yang seterusnya. Guru mengingatkan murid mengekalkan langkah rendah semasa bertukar kepada jalan.", "Guru memberi soalan lisan satu demi satu tentang nama jantung, oksigen daripada paru-paru dan contoh aktiviti. Guru mengulang contoh ayat serta langkah bila diperlukan."], "pupil_steps": ["Sebelum bergerak, semak kasut, pakaian dan ruang; minum jika perlu. Selepas pemanasan, cuba langkah kanan-kiri diikuti jalan setempat dengan kumpulan.", "Lakukan rangkaian 2 minit: langkah ke sisi 30 saat dan jalan setempat 30 saat, kemudian ulang sekali. Kekalkan nafas biasa; berhenti dan beritahu guru jika tidak selesa.", "Dalam rehat, minum jika perlu dan namakan jantung sebagai organ yang mengepam darah. Sebut paru-paru membekalkan oksigen ke dalam darah lalu jantung mengepam darah itu ke seluruh badan. Beri contoh tarian aerobik yang boleh menguatkan jantung jika diamalkan.", "Pada giliran A atau B, tunjuk rangkaian sendiri sementara pasangan berehat. Beri galakan kepada kumpulan dan kongsi gerakan yang disukai jika mahu. Akhiri dengan penyejukan, minum selepas dan semak keadaan diri."], "product": "Rangkaian sisi-jalan individu dalam segmen yang dilihat guru, jawapan ringkas tentang jantung/paru-paru serta contoh aktiviti dan respons kumpulan.", "criterion": "Murid bergerak bersambung sepanjang 2 minit yang ditetapkan apabila mampu. Berhenti awal tidak dikira lengkap; masa sebenar dan bantuan direkod tanpa hukuman. Hubungan kedua-dua organ mesti disebut, bukan nama organ sahaja.", "next_step": "Jika pertukaran gerakan masih terhenti, guru memberi contoh dan arahan lebih awal. Jangan tambah kelajuan; teruskan bantuan dan berikan peluang lain jika murid memerlukan rehat.", "example": {"teacher": "Kaki sudah rapat? Sekarang jalan. Semasa bergerak, bagaimana paru-paru dan jantung membantu badan?", "pupil": "Murid menyambung jalan; selepas rehat menjawab “Paru-paru beri oksigen ke dalam darah. Jantung pam darah itu ke seluruh badan.”"}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas pertukaran daripada langkah ke sisi kepada jalan setempat tanpa menambah masa.", "materials": ["Ruang sendiri dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 51"], "teacher": ["Guru menunjukkan pertukaran yang lancar dengan langkah kecil dan tangan di bawah bahu. Guru memberi satu maklum balas tentang ruang atau kaki yang tidak bersilang.", "Guru membantu jawapan paru-paru, oksigen dalam darah dan jantung melalui dua ayat pendek. Guru tetap memberi isyarat pertukaran serta membenarkan contoh semula sepanjang giliran."], "pupil_steps": ["Sebelum aktiviti, semak kasut dan ruang, sediakan botol serta minum jika perlu. Selepas pemanasan, cuba sambungan sisi-jalan dengan kaki tidak bersilang.", "Lakukan rangkaian 2 minit yang sama: langkah ke sisi 30 saat dan jalan 30 saat, kemudian ulang sekali. Perkemas pertukaran dengan tenang sambil bernafas biasa; berhenti jika perlu dan maklumkan guru.", "Semasa rehat, minum dan sebut sendiri “Jantung mengepam darah”. Terangkan secara ringkas bahawa paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti.", "Tunjuk rangkaian sendiri dengan pertukaran langkah yang terkawal. Berehat dan memberi galakan kepada rakan; kongsi pengalaman seronok hanya jika benar dirasai. Ikut penyejukan, minum selepas dan beritahu keadaan diri."], "product": "Rangkaian individu dengan pertukaran terkawal dan tempoh sebenar, jawapan kedua-dua organ serta aktiviti, dan respons semasa bersama kumpulan.", "criterion": "Murid memperkemas pertukaran dalam tempoh 2 minit yang sama; bukan bergerak lebih laju atau lebih lama. Guru menyemak lakuan berterusan serta jawapan jantung, paru-paru dan aktiviti setiap murid.", "next_step": "Gunakan satu sasaran kecil, iaitu kaki tidak bersilang atau pertukaran yang tenang. Kembali kepada contoh guru jika perlu; jangan menambah masa untuk murid yang perlu berehat.", "example": {"teacher": "Boleh sambung jalan tanpa langkah besar? Aktiviti apa yang boleh menguatkan jantung jika diamalkan?", "pupil": "Murid memperkemas pertukaran dan menjawab “Tarian aerobik”. Apabila ditanya lagi, murid melengkapkan hubungan paru-paru dan jantung."}}}, "differentiation_delivery": {"common_task": "Murid dapat menyambung langkah ke sisi dan jalan setempat secara berterusan dalam masa yang ditetapkan guru.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Minit 6–10: bimbing langkah ke sisi dan sambungan jalan; ajar hubungan paru-paru dengan jantung.", "Minit 11–13 dan 15–17: guru melihat murid berlainan sepanjang segmen yang dipilih. Dalam rehat 13–15 serta 17–19, dapatkan jawapan individu dan rekod bantuan.", "Minit 20–22: lihat A; 23–25: lihat B. Murid lain kekal dalam pandangan dan berehat di ruang sendiri. Catat jika mana-mana segmen tidak dapat diperhatikan penuh.", "Minit 25–30: lengkapkan jawapan yang sempat serta semak keadaan selepas aktiviti. Senaraikan nama dan aspek belum diperhatikan untuk peluang susulan."], "individual_check": "Melakukan rangkaian langkah ke sisi dan jalan setempat selama 2 minit mengikut kemampuan.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu dengan jam randik pada latihan 11–13 atau 15–17, kemudian giliran A 20–22 dan B 23–25.", "evidence": "Rangkaian langkah ke sisi dan jalan setempat yang disambung dalam segmen 2 minit; catatan masa mula/tamat, bantuan dan masa berhenti sebenar.", "criterion": "Murid bergerak berterusan selama 2 minit yang ditetapkan guru, dengan langkah ringan dan bantuan yang diperlukan. Jika berhenti awal, catat tempoh sebenar dan bukti yang belum lengkap tanpa menganggapnya selesai atau menghukum keperluan rehat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; segmen diperhatikan: ____; langkah ke sisi: ____; jalan setempat: ____.", "Tempoh sebenar: ____; gerakan bersambung: ____; bantuan/rehat: ____; susulan: ____."]}, "pbd_complementary": {"4.2.1": {"method": "Soal jawab individu ketika berhenti pada minit 10–11, 13–15, 22–23 atau 25–26.", "evidence": "Murid menamakan jantung sebagai organ utama yang mengepam darah.", "criterion": "Jawapan “Jantung” disebut murid sendiri. Menunjuk dada atau mengikut suara rakan sahaja belum cukup; bantuan lisan dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; jawapan organ: ____; bantuan: ____; belum diperoleh: ____."]}, "4.2.2": {"method": "Guru bertanya hubungan organ kepada individu dalam rehat minit 13–15, 17–19, 22–23 atau 25–26.", "evidence": "Murid menyebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak.", "criterion": "Kedua-dua bahagian hubungan disebut melalui ayat pendek. Guru boleh memberi kata mula atau contoh semula; tiada penerangan mekanisme yang panjang diperlukan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; paru-paru/oksigen ke dalam darah: ____; jantung mengepam darah ke seluruh badan: ____; bantuan: ____."]}, "4.2.3": {"method": "Soal jawab individu semasa rehat minit 17–19, 25–26 atau penutup 29–30.", "evidence": "Contoh aktiviti yang disebut sendiri, seperti tarian aerobik atau berlari.", "criterion": "Murid menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan. Jawapan bukan dakwaan bahawa jantung telah bertambah kuat selepas kelas ini.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; aktiviti yang disebut: ____; bantuan: ____; belum dijawab: ____."]}, "5.4.2": {"method": "Pemerhatian respons individu semasa rangkaian berkumpulan 11–17 dan giliran 20–25; pertanyaan sukarela dalam rehat 17–19 atau 25–26.", "evidence": "Kata atau isyarat yang menunjukkan seronok melakukan rangkaian bersama rakan, contohnya menyebut gerakan kegemaran bersama kumpulan atau mahu mencuba bersama lagi.", "criterion": "Guru merekod respons seronok yang benar-benar dilihat atau didengar. Ikut arahan sahaja bukan bukti rasa seronok; murid yang pendiam, berhenti awal atau memerlukan bantuan tidak dilabel negatif.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; kata/isyarat sebenar dan konteks kumpulan: ____; bantuan/keperluan tubuh: ____; belum diperhatikan: ____."]}}, "intervention": ["Guru menggunakan langkah ke sisi yang lebih kecil dan memberi contoh menghadap arah yang sama. Bantuan dikekalkan semasa pentaksiran jika diperlukan.", "Murid yang perlu berhenti diberi rehat; masa sebenar dan sebab yang dimaklumkan dicatat. Tiada paksaan mengganti minit, menambah kelajuan atau membandingkan kecergasan murid.", "Untuk hubungan organ, ulang dua ayat pendek: paru-paru membekalkan oksigen ke dalam darah; jantung mengepam darah itu ke seluruh badan. Dapatkan jawapan murid sendiri dengan bantuan.", "Jika bukti belum diperoleh, catat aspek serta nama untuk susulan. Tiada keputusan pencapaian atau peningkatan kecergasan diisi sebelum PdP."], "book_pages_text": "50, 51", "sp_focus": "", "sp_display": "3.2.1", "complementary": [{"standard_key": "4.2.1", "sp_code": "4.2.1", "sp_text": "Menamakan organ utama yang mengepam darah.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.2", "sp_code": "4.2.2", "sp_text": "Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.2.3", "sp_code": "4.2.3", "sp_text": "Menyatakan aktiviti yang boleh menguatkan jantung.", "sk_code": "4.2", "sk_text": "Mengaplikasi konsep asas kapasiti aerobik.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "8677630fbc5ef1ee269d7ed015be65d7fa81926d35ba6bb0a42c6e74e977fe5e"}'::jsonb,'[{"kind": "title", "text": "Minggu 34 Sesi 2 — Langkah ke sisi dan jalan berirama"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W34-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Jantung Kuat, Badan Sihat"}, {"kind": "p", "text": "Aktiviti guru: Langkah ke sisi dan jalan berirama"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 50, 51."}, {"kind": "p", "text": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 belajar rangkaian; 10–19 latihan dan rehat; 19–26 giliran individu; 26–30 penyejukan. Guru menetapkan segmen 2 minit: langkah ke sisi 30 saat, jalan setempat 30 saat, kemudian ulang urutan sekali. Segmen latihan 11–13 dan 15–17 diselang rehat 13–15 dan 17–19. Semakan A 20–22 dan B 23–25 diselang rehat 22–23. Minum sebelum, pada rehat yang ditetapkan dan selepas; rehat tambahan dibenarkan tanpa memotong penyejukan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.2: Melakukan aktiviti yang meningkatkan kapasiti aerobik."}, {"kind": "p", "text": "SP utama 3.2.1: Melakukan aktiviti berterusan dalam jangka masa yang ditetapkan."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.1: Menamakan organ utama yang mengepam darah."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.2: Menyatakan hubungan antara jantung dengan paru-paru semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SK sokongan 4.2: Mengaplikasi konsep asas kapasiti aerobik."}, {"kind": "p", "text": "SP sokongan 4.2.3: Menyatakan aktiviti yang boleh menguatkan jantung."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.2: Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat menyambung langkah ke sisi dan jalan setempat secara berterusan dalam masa yang ditetapkan guru."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan rangkaian langkah ke sisi dan jalan setempat selama 2 minit mengikut kemampuan."}, {"kind": "p", "text": "2. Menamakan jantung serta menyebut hubungan paru-paru, oksigen dalam darah dan jantung."}, {"kind": "p", "text": "3. Menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah melakukan senamrobik mudah secara bersambung dan berehat selepas segmen pendek."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 6 buah"}, {"kind": "p", "text": "Kegunaan: Empat kon menandakan tepi kawasan langkah ke sisi dan dua kon menandakan ruang rehat; semuanya di luar tempat pijakan."}, {"kind": "label", "text": "Jam randik"}, {"kind": "p", "text": "Keperluan: 1 buah untuk guru"}, {"kind": "p", "text": "Kegunaan: Menandakan rangkaian 2 minit dan waktu rehat; masa berhenti awal dicatat secara sebenar."}, {"kind": "label", "text": "Botol air minuman sendiri"}, {"kind": "p", "text": "Keperluan: 1 bagi setiap murid"}, {"kind": "p", "text": "Kegunaan: Diletakkan di ruang rehat untuk minum sebelum, semasa rehat dan selepas aktiviti."}, {"kind": "label", "text": "Buku teks PJPK Tahun 1"}, {"kind": "p", "text": "Keperluan: 1 naskhah guru, halaman 50–51"}, {"kind": "p", "text": "Kegunaan: Rujukan senamrobik berkumpulan, jantung dan paru-paru."}, {"kind": "label", "text": "Senarai semak dan pen guru"}, {"kind": "p", "text": "Keperluan: 1 set"}, {"kind": "p", "text": "Kegunaan: Merekod langkah individu, tempoh yang dilihat, jawapan dan bantuan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memeriksa permukaan rata, kering dan tidak licin. Semua kon berada di tepi, bukan di laluan kaki."}, {"kind": "p", "text": "2. Guru menyediakan ruang sendiri dengan jarak sekurang-kurangnya dua depa antara murid. Uji satu langkah kecil ke kanan dan kiri untuk memastikan ruang tidak bertindih."}, {"kind": "p", "text": "3. Ruang rehat serta botol berada di tepi kawasan dalam pandangan guru. Guru memeriksa pakaian, kasut dan keadaan murid sebelum menetapkan segmen 2 minit yang ringan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "Murid bersenam dalam kumpulan kecil di ruang masing-masing; tiada berjalan mengelilingi kon. Pasangan A dan B dalam kumpulan bergilir untuk semakan: A pada 20–22, B pada 23–25. Rakan menunggu di ruang sendiri sambil berehat. Murid tanpa pasangan menunjukkan gerakan berhampiran guru. Arahan “Berhenti” bermaksud hentikan langkah di tempat selamat dan pandang guru. Murid tidak berlumba, menyilangkan kaki atau masuk ke ruang rakan."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Langkah kecil ke kanan. Rapatkan kaki tanpa bersilang. Ulang ke kiri."}, {"kind": "p", "text": "2. Apabila cikgu sebut “jalan”, jalan di tempat sendiri sambil mengayun tangan rendah."}, {"kind": "p", "text": "3. Tukar gerakan dengan tenang. Tidak perlu melompat atau mengangkat lutut tinggi."}, {"kind": "p", "text": "4. Bernafas seperti biasa. Perlahankan langkah atau berhenti jika tidak selesa."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 6 buah"}, {"kind": "p", "text": "2. Jam randik — 1 buah untuk guru"}, {"kind": "p", "text": "3. Botol air minuman sendiri — 1 bagi setiap murid"}, {"kind": "p", "text": "4. Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 50–51"}, {"kind": "p", "text": "5. Senarai semak dan pen guru — 1 set"}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid melakukan rangkaian bersama kumpulan kecil dan menyokong giliran A serta B. Rakan memberi satu galakan seperti “langkah kecil” tanpa menyentuh atau mendesak. Semasa rehat, murid berkongsi gerakan yang disukai jika mahu dan setiap orang menjawab soalan organ sendiri."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Langkah ke sisi dibuat kecil tanpa menyilangkan kaki, melompat atau menukar arah secara mengejut. Kon dan botol berada di luar kawasan pijakan."}, {"kind": "p", "text": "5. Tempoh 2 minit ditetapkan sebagai latihan ringan yang pendek. Murid boleh berhenti lebih awal dan beritahu guru; catat masa sebenar serta keperluan tubuh tanpa hukuman atau perbandingan."}, {"kind": "p", "text": "6. Guru memastikan murid bernafas seperti biasa. Murid yang sakit, pening atau sukar bernafas dihentikan daripada aktiviti dan diberi perhatian mengikut tatacara sekolah."}, {"kind": "p", "text": "7. Tiada sasaran nadi, tahan nafas atau ujian maksimum. Rehat, bantuan dan langkah yang lebih kecil dibenarkan sepanjang sesi."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 0–1: guru memeriksa pakaian, kasut, keadaan murid, permukaan dan kedudukan kon. Guru menunjukkan ruang rehat serta tempat botol."}, {"kind": "p", "text": "2. Minit 1–2: guru menguji ruang langkah kanan dan kiri, menerangkan arahan “Berhenti” dan memberi peluang minum sebelum aktiviti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membetulkan pakaian serta kasut dan memberitahu guru jika tidak sihat. Murid membawa botol sendiri ke ruang rehat."}, {"kind": "p", "text": "2. Murid mencuba satu langkah kecil ke sisi tanpa menghampiri rakan, kemudian berhenti mengikut suara guru. Murid minum jika perlu."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Buku teks PJPK Tahun 1 Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 2–4: guru memimpin berjalan setempat dengan langkah rendah serta ayunan tangan santai, bukan larian."}, {"kind": "p", "text": "2. Minit 4–5: guru menunjukkan gerakan membuka tangan ke sisi dan merapatkannya dengan lembut. Minit 5–6: guru membimbing regangan betis kanan dan kiri dengan tumit belakang di lantai."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan di ruang sendiri sambil bernafas seperti biasa dan menjaga jarak."}, {"kind": "p", "text": "2. Murid menggerakkan tangan serta meregang betis setakat selesa tanpa henjutan. Murid memaklumkan guru jika perlu berehat."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Belajar sambungan sisi dan jalan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 6–7: guru menunjukkan langkah kecil ke kanan, rapatkan kaki, kemudian ke kiri dan rapatkan kaki. Kaki tidak bersilang dan badan kekal menghadap depan."}, {"kind": "p", "text": "2. Minit 7–8: guru menunjukkan jalan setempat dengan ayunan tangan rendah. Guru mengingatkan murid bergerak dalam ruang sendiri."}, {"kind": "p", "text": "3. Minit 8–9: guru memimpin contoh rangkaian pendek, iaitu langkah ke sisi 30 saat dan jalan setempat 30 saat tanpa hentian di antaranya. Murid boleh berhenti jika perlu."}, {"kind": "p", "text": "4. Minit 9–10: semua berehat dan mendapat peluang minum. Guru merujuk buku halaman 51 dan menyebut “Paru-paru membekalkan oksigen ke dalam darah. Jantung mengepam darah itu ke seluruh badan.”"}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru langkah ke kanan dan kiri dengan kecil. Murid merapatkan kaki tanpa menyilangkan kaki atau menghampiri rakan."}, {"kind": "p", "text": "2. Murid menyambung langkah ke sisi dengan jalan setempat apabila mendengar arahan guru. Murid mengayun tangan rendah dan bernafas biasa."}, {"kind": "p", "text": "3. Murid berhenti dan minum pada waktu rehat. Murid mencuba sebutan “jantung” serta “paru-paru” dengan bimbingan."}, {"kind": "p", "text": "Semakan: Guru memastikan rangkaian difahami sebelum menambah kepada tempoh 2 minit. Penerangan organ ialah pengajaran awal, bukan keputusan PBD semua murid."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Buku teks halaman 50–51 Botol air minuman sendiri"}, {"kind": "h3", "text": "Langkah 4: Rangkaian dua minit dengan rehat — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 10–11: ketika murid masih berehat, guru bertanya organ yang mengepam darah. Guru menerangkan dengan ayat pendek bahawa paru-paru memberi oksigen ke dalam darah dan jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak."}, {"kind": "p", "text": "2. Minit 11–13: guru memimpin langkah ke sisi 30 saat dan jalan setempat 30 saat, kemudian mengulang urutan sekali. Guru menetapkan 2 minit dengan jam randik serta membenarkan berhenti lebih awal."}, {"kind": "p", "text": "3. Minit 13–15: semua berehat/minum. Guru memberi satu pembetulan mudah pada langkah dan mendapatkan jawapan individu tentang hubungan jantung dengan paru-paru."}, {"kind": "p", "text": "4. Minit 15–17: ulang rangkaian 2 minit yang sama jika murid selesa. Guru memberi bantuan mengikut keperluan, bukan menambah kelajuan atau jarak."}, {"kind": "p", "text": "5. Minit 17–19: semua berehat/minum. Guru meminta contoh aktiviti yang boleh menguatkan jantung jika diamalkan, seperti tarian aerobik. Guru bertanya gerakan yang disukai dalam kumpulan tanpa memaksa respons."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjawab sendiri tentang jantung ketika berhenti dan mendengar penerangan hubungan dengan paru-paru."}, {"kind": "p", "text": "2. Murid menyambung langkah ke sisi dan jalan setempat mengikut arahan guru selama tempoh yang ditetapkan, dengan nafas biasa. Murid boleh berhenti lebih awal dan memberitahu guru."}, {"kind": "p", "text": "3. Dalam rehat, murid minum jika perlu. Murid menjawab dalam dua ayat pendek tentang paru-paru yang memberi oksigen ke dalam darah dan jantung yang mengepam darah itu ke seluruh badan."}, {"kind": "p", "text": "4. Murid mencuba rangkaian kedua jika selesa dan memberi ruang kepada rakan yang berehat. Selepas berhenti, murid menyebut satu contoh aktiviti dan boleh berkongsi gerakan yang disukai."}, {"kind": "p", "text": "Semakan: 3.2.1: kesinambungan sisi-jalan dan tempoh sebenar setiap murid yang diperhatikan. 4.2.1, 4.2.2, 4.2.3: jawapan sendiri. 5.4.2: respons sebenar ketika bersama kumpulan, bukan andaian kerana murid ikut arahan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 5: Giliran menunjukkan rangkaian sendiri — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 19–20: guru menetapkan A dan B dalam kumpulan. Guru mengulang bahawa setiap giliran ialah 2 minit dan murid boleh berhenti jika perlu."}, {"kind": "p", "text": "2. Minit 20–22: A melakukan rangkaian sisi-jalan; B berehat di ruang sendiri. Guru memerhatikan murid yang disasarkan sambil memastikan semua kekal dalam pandangan."}, {"kind": "p", "text": "3. Minit 22–23: semua berehat/minum; guru mengambil jawapan pendek yang belum didengar. Minit 23–25: B menunjukkan rangkaian yang sama dan A berehat."}, {"kind": "p", "text": "4. Minit 25–26: semua berhenti. Guru bertanya nama organ, hubungan dengan paru-paru atau contoh aktiviti kepada murid yang belum disemak. Guru mencatat aspek yang belum sempat diperhatikan untuk susulan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Pada giliran sendiri, murid melakukan langkah ke sisi dan jalan setempat mengikut perubahan arahan guru. Murid tidak menambah kelajuan untuk menarik perhatian."}, {"kind": "p", "text": "2. Murid yang menunggu berehat di ruang sendiri dan memberi galakan sopan. Murid minum mengikut keperluan serta menghormati rakan yang berhenti awal."}, {"kind": "p", "text": "3. Selepas berhenti, murid menjawab guru sendiri dengan bantuan jika perlu. Murid boleh menyebut gerakan yang seronok dilakukan bersama kumpulan atau memberitahu jika belum selesa."}, {"kind": "p", "text": "Semakan: Guru merekod segmen yang dilihat penuh atau masa berhenti sebenar. Bukti kumpulan tidak menggantikan pemerhatian gerakan dan jawapan setiap murid."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 26–27: guru memimpin jalan perlahan setempat. Minit 27–29: guru membimbing regangan tangan dan betis kanan serta kiri yang lembut, tanpa memaksa jarak regangan."}, {"kind": "p", "text": "2. Minit 29–30: guru memberi masa minum dan memeriksa keadaan murid. Guru mendapatkan jawapan ringkas yang belum diperoleh jika sempat, kemudian mengarahkan botol sendiri dikemas."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan perlahan, kemudian meregang tangan dan betis sambil bernafas biasa. Murid tidak kembali berlari."}, {"kind": "p", "text": "2. Murid minum mengikut keperluan, mengemas botol dan memberitahu jika masih tidak selesa. Murid yang ditanya memberi satu jawapan sendiri tentang aktiviti atau organ."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Langkah ke kanan dan rapat. Langkah ke kiri dan rapat. Sekarang jalan di tempat sendiri. Kita terus bergerak dengan ringan selama dua minit; kamu boleh berhenti jika perlu."}, {"kind": "p", "text": "Murid: Murid menyambung langkah ke sisi dengan jalan setempat mengikut suara guru. Selepas berhenti, murid menjawab soalan jantung dan paru-paru."}, {"kind": "p", "text": "Semakan guru: Guru melihat kawalan ruang serta gerakan yang bersambung dan merekod tempoh sebenar. Masa 2 minit bukan ujian usaha maksimum atau bukti kecergasan telah bertambah."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W34-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat menyambung langkah ke sisi dan jalan setempat secara berterusan dalam masa yang ditetapkan guru."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Minit 6–10: bimbing langkah ke sisi dan sambungan jalan; ajar hubungan paru-paru dengan jantung."}, {"kind": "p", "text": "2. Minit 11–13 dan 15–17: guru melihat murid berlainan sepanjang segmen yang dipilih. Dalam rehat 13–15 serta 17–19, dapatkan jawapan individu dan rekod bantuan."}, {"kind": "p", "text": "3. Minit 20–22: lihat A; 23–25: lihat B. Murid lain kekal dalam pandangan dan berehat di ruang sendiri. Catat jika mana-mana segmen tidak dapat diperhatikan penuh."}, {"kind": "p", "text": "4. Minit 25–30: lengkapkan jawapan yang sempat serta semak keadaan selepas aktiviti. Senaraikan nama dan aspek belum diperhatikan untuk peluang susulan."}, {"kind": "p", "text": "Semakan individu: Melakukan rangkaian langkah ke sisi dan jalan setempat selama 2 minit mengikut kemampuan."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Menyambung langkah ke sisi yang kecil dan jalan setempat sambil meniru guru."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di tepi"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 51 untuk contoh lisan guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru berdiri menghadap arah yang sama berhampiran murid supaya kanan dan kiri mudah diikuti. Guru memberi arahan “sisi, rapat, jalan” satu demi satu; ayunan tangan boleh kekal semula jadi."}, {"kind": "p", "text": "2. Guru memberi kata mula dan mengulang hubungan paru-paru dengan jantung dalam dua ayat pendek. Guru mendengar jawapan individu dalam rehat serta mencatat bantuan, bukan menjawab bagi pihak murid."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, periksa kasut dan ruang dengan bantuan guru serta minum jika perlu. Selepas pemanasan, cuba langkah kecil ke kanan dan kiri tanpa menyilangkan kaki."}, {"kind": "p", "text": "2. Dalam segmen 2 minit yang ditetapkan, ikut guru melakukan langkah ke sisi 30 saat dan jalan setempat 30 saat, lalu ulang urutan sekali. Bernafas biasa; berhenti dan maklumkan guru jika perlu rehat."}, {"kind": "p", "text": "3. Semasa rehat, minum dan jawab sendiri “Jantung mengepam darah”. Dengan bantuan, sebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti."}, {"kind": "p", "text": "4. Pada giliran sendiri, tunjuk rangkaian yang sama dengan contoh guru. Berehat ketika rakan bergerak; beri galakan atau kongsi rasa sebenar jika mahu. Ikut penyejukan, minum selepas dan beritahu keadaan diri."}, {"kind": "p", "text": "Contoh guru: Ikut cikgu ke sisi, rapat, kemudian jalan. Selepas rehat, apa yang paru-paru bekalkan ke dalam darah?"}, {"kind": "p", "text": "Contoh respons murid: Murid meniru rangkaian dan menjawab dengan bantuan “Oksigen. Jantung mengepam darah itu ke seluruh badan.”"}, {"kind": "p", "text": "Hasil individu: Percubaan rangkaian sisi-jalan individu dengan tempoh sebenar, jawapan sendiri tentang kedua-dua organ dan contoh aktiviti serta respons bersama kumpulan."}, {"kind": "p", "text": "Kriteria: Guru melihat usaha menyambung gerakan bagi tempoh 2 minit yang ditetapkan. Jika murid berhenti awal, catat masa sebenar dan bukti berterusan yang belum lengkap. Nama jantung, hubungan paru-paru-jantung dan contoh aktiviti dinilai dengan bantuan lisan."}, {"kind": "p", "text": "Susulan: Kekalkan langkah kecil dan contoh berdekatan. Rehat tambahan dibenarkan; susulan diberi mengikut kesediaan tanpa meminta murid mengganti masa yang terlepas."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Menyambung langkah kanan-kiri dan jalan setempat dengan bantuan suara guru."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan dalam kumpulan dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 50–51"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan kaki dirapatkan tanpa bersilang sebelum langkah ke sisi yang seterusnya. Guru mengingatkan murid mengekalkan langkah rendah semasa bertukar kepada jalan."}, {"kind": "p", "text": "2. Guru memberi soalan lisan satu demi satu tentang nama jantung, oksigen daripada paru-paru dan contoh aktiviti. Guru mengulang contoh ayat serta langkah bila diperlukan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum bergerak, semak kasut, pakaian dan ruang; minum jika perlu. Selepas pemanasan, cuba langkah kanan-kiri diikuti jalan setempat dengan kumpulan."}, {"kind": "p", "text": "2. Lakukan rangkaian 2 minit: langkah ke sisi 30 saat dan jalan setempat 30 saat, kemudian ulang sekali. Kekalkan nafas biasa; berhenti dan beritahu guru jika tidak selesa."}, {"kind": "p", "text": "3. Dalam rehat, minum jika perlu dan namakan jantung sebagai organ yang mengepam darah. Sebut paru-paru membekalkan oksigen ke dalam darah lalu jantung mengepam darah itu ke seluruh badan. Beri contoh tarian aerobik yang boleh menguatkan jantung jika diamalkan."}, {"kind": "p", "text": "4. Pada giliran A atau B, tunjuk rangkaian sendiri sementara pasangan berehat. Beri galakan kepada kumpulan dan kongsi gerakan yang disukai jika mahu. Akhiri dengan penyejukan, minum selepas dan semak keadaan diri."}, {"kind": "p", "text": "Contoh guru: Kaki sudah rapat? Sekarang jalan. Semasa bergerak, bagaimana paru-paru dan jantung membantu badan?"}, {"kind": "p", "text": "Contoh respons murid: Murid menyambung jalan; selepas rehat menjawab “Paru-paru beri oksigen ke dalam darah. Jantung pam darah itu ke seluruh badan.”"}, {"kind": "p", "text": "Hasil individu: Rangkaian sisi-jalan individu dalam segmen yang dilihat guru, jawapan ringkas tentang jantung/paru-paru serta contoh aktiviti dan respons kumpulan."}, {"kind": "p", "text": "Kriteria: Murid bergerak bersambung sepanjang 2 minit yang ditetapkan apabila mampu. Berhenti awal tidak dikira lengkap; masa sebenar dan bantuan direkod tanpa hukuman. Hubungan kedua-dua organ mesti disebut, bukan nama organ sahaja."}, {"kind": "p", "text": "Susulan: Jika pertukaran gerakan masih terhenti, guru memberi contoh dan arahan lebih awal. Jangan tambah kelajuan; teruskan bantuan dan berikan peluang lain jika murid memerlukan rehat."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas pertukaran daripada langkah ke sisi kepada jalan setempat tanpa menambah masa."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 51"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan pertukaran yang lancar dengan langkah kecil dan tangan di bawah bahu. Guru memberi satu maklum balas tentang ruang atau kaki yang tidak bersilang."}, {"kind": "p", "text": "2. Guru membantu jawapan paru-paru, oksigen dalam darah dan jantung melalui dua ayat pendek. Guru tetap memberi isyarat pertukaran serta membenarkan contoh semula sepanjang giliran."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, semak kasut dan ruang, sediakan botol serta minum jika perlu. Selepas pemanasan, cuba sambungan sisi-jalan dengan kaki tidak bersilang."}, {"kind": "p", "text": "2. Lakukan rangkaian 2 minit yang sama: langkah ke sisi 30 saat dan jalan 30 saat, kemudian ulang sekali. Perkemas pertukaran dengan tenang sambil bernafas biasa; berhenti jika perlu dan maklumkan guru."}, {"kind": "p", "text": "3. Semasa rehat, minum dan sebut sendiri “Jantung mengepam darah”. Terangkan secara ringkas bahawa paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah itu ke seluruh badan. Namakan tarian aerobik sebagai contoh aktiviti."}, {"kind": "p", "text": "4. Tunjuk rangkaian sendiri dengan pertukaran langkah yang terkawal. Berehat dan memberi galakan kepada rakan; kongsi pengalaman seronok hanya jika benar dirasai. Ikut penyejukan, minum selepas dan beritahu keadaan diri."}, {"kind": "p", "text": "Contoh guru: Boleh sambung jalan tanpa langkah besar? Aktiviti apa yang boleh menguatkan jantung jika diamalkan?"}, {"kind": "p", "text": "Contoh respons murid: Murid memperkemas pertukaran dan menjawab “Tarian aerobik”. Apabila ditanya lagi, murid melengkapkan hubungan paru-paru dan jantung."}, {"kind": "p", "text": "Hasil individu: Rangkaian individu dengan pertukaran terkawal dan tempoh sebenar, jawapan kedua-dua organ serta aktiviti, dan respons semasa bersama kumpulan."}, {"kind": "p", "text": "Kriteria: Murid memperkemas pertukaran dalam tempoh 2 minit yang sama; bukan bergerak lebih laju atau lebih lama. Guru menyemak lakuan berterusan serta jawapan jantung, paru-paru dan aktiviti setiap murid."}, {"kind": "p", "text": "Susulan: Gunakan satu sasaran kecil, iaitu kaki tidak bersilang atau pertukaran yang tenang. Kembali kepada contoh guru jika perlu; jangan menambah masa untuk murid yang perlu berehat."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu dengan jam randik pada latihan 11–13 atau 15–17, kemudian giliran A 20–22 dan B 23–25."}, {"kind": "p", "text": "Bukti: Rangkaian langkah ke sisi dan jalan setempat yang disambung dalam segmen 2 minit; catatan masa mula/tamat, bantuan dan masa berhenti sebenar."}, {"kind": "p", "text": "Kriteria: Murid bergerak berterusan selama 2 minit yang ditetapkan guru, dengan langkah ringan dan bantuan yang diperlukan. Jika berhenti awal, catat tempoh sebenar dan bukti yang belum lengkap tanpa menganggapnya selesai atau menghukum keperluan rehat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; segmen diperhatikan: ____; langkah ke sisi: ____; jalan setempat: ____."}, {"kind": "p", "text": "2. Tempoh sebenar: ____; gerakan bersambung: ____; bantuan/rehat: ____; susulan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu ketika berhenti pada minit 10–11, 13–15, 22–23 atau 25–26."}, {"kind": "p", "text": "Bukti: Murid menamakan jantung sebagai organ utama yang mengepam darah."}, {"kind": "p", "text": "Kriteria: Jawapan “Jantung” disebut murid sendiri. Menunjuk dada atau mengikut suara rakan sahaja belum cukup; bantuan lisan dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; jawapan organ: ____; bantuan: ____; belum diperoleh: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.2"}, {"kind": "p", "text": "Kaedah: Guru bertanya hubungan organ kepada individu dalam rehat minit 13–15, 17–19, 22–23 atau 25–26."}, {"kind": "p", "text": "Bukti: Murid menyebut paru-paru membekalkan oksigen ke dalam darah dan jantung mengepam darah yang membawa oksigen itu ke seluruh badan semasa bergerak."}, {"kind": "p", "text": "Kriteria: Kedua-dua bahagian hubungan disebut melalui ayat pendek. Guru boleh memberi kata mula atau contoh semula; tiada penerangan mekanisme yang panjang diperlukan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; paru-paru/oksigen ke dalam darah: ____; jantung mengepam darah ke seluruh badan: ____; bantuan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.2.3"}, {"kind": "p", "text": "Kaedah: Soal jawab individu semasa rehat minit 17–19, 25–26 atau penutup 29–30."}, {"kind": "p", "text": "Bukti: Contoh aktiviti yang disebut sendiri, seperti tarian aerobik atau berlari."}, {"kind": "p", "text": "Kriteria: Murid menamakan satu aktiviti yang boleh menguatkan jantung jika diamalkan. Jawapan bukan dakwaan bahawa jantung telah bertambah kuat selepas kelas ini."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; aktiviti yang disebut: ____; bantuan: ____; belum dijawab: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons individu semasa rangkaian berkumpulan 11–17 dan giliran 20–25; pertanyaan sukarela dalam rehat 17–19 atau 25–26."}, {"kind": "p", "text": "Bukti: Kata atau isyarat yang menunjukkan seronok melakukan rangkaian bersama rakan, contohnya menyebut gerakan kegemaran bersama kumpulan atau mahu mencuba bersama lagi."}, {"kind": "p", "text": "Kriteria: Guru merekod respons seronok yang benar-benar dilihat atau didengar. Ikut arahan sahaja bukan bukti rasa seronok; murid yang pendiam, berhenti awal atau memerlukan bantuan tidak dilabel negatif."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; kata/isyarat sebenar dan konteks kumpulan: ____; bantuan/keperluan tubuh: ____; belum diperhatikan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Guru menggunakan langkah ke sisi yang lebih kecil dan memberi contoh menghadap arah yang sama. Bantuan dikekalkan semasa pentaksiran jika diperlukan."}, {"kind": "p", "text": "2. Murid yang perlu berhenti diberi rehat; masa sebenar dan sebab yang dimaklumkan dicatat. Tiada paksaan mengganti minit, menambah kelajuan atau membandingkan kecergasan murid."}, {"kind": "p", "text": "3. Untuk hubungan organ, ulang dua ayat pendek: paru-paru membekalkan oksigen ke dalam darah; jantung mengepam darah itu ke seluruh badan. Dapatkan jawapan murid sendiri dengan bantuan."}, {"kind": "p", "text": "4. Jika bukti belum diperoleh, catat aspek serta nama untuk susulan. Tiada keputusan pencapaian atau peningkatan kecergasan diisi sebelum PdP."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tarian aerobik BT51 serta jalan/larian ringan daripada BT50 disesuaikan dengan ruang sendiri. Tiada papan roda, bangku tinggi atau perlumbaan. Segmen berterusan pendek ditetapkan guru; rehat apabila perlu. Jantung, paru-paru dan contoh aktiviti dijejak untuk setiap murid.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W35-S1','pj',1,2026,35,1,30,'3.3.1',array[52,53,54,55]::int[],'fbc8aafdc254b19d528078b032d77a7e6568c9a6e0fc26da4e7164accd7c16bd','4c2c9f76b25250a924083f68f9ebe1a46219d28e3e0005cc76a3ef84c4034227','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W35-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 35, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Siap Siaga", "source_title": "Siap Siaga", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T12-R3", "source_row_literal": ["35\n\nKump A: 04.10.2026-08.10.2026\n\nKump B: 05.10.2026- 09.10.2026", "8: CERGAS DAN MANTAP\n\nSIAP SIAGA", "3.3 Melakukan senaman kelenturan dengan lakuan yang betul.\n4.3 Mengaplikasi konsep asas kelenturan\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "3.3.1  Melakukan aktiviti regangan dinamik dan statik pada otot-otot utama.\n\n4.3.1 Mengenal pasti cara regangan yang betul.\n4.3.2  Mengenali pelbagai pergerakan \nyang betul untuk meningkatkan \nkelenturan pada sesuatu kumpulan \notot.\n4.3.3  Mengetahui bahawa aktiviti \nregangan dapat meningkatkan \nkecekapan fungsi otot.\n\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\nPermainan kecil:\nRegangan rahsia\n\nBT m/s 52-53"], "rpt_original_page_literal": "52-53", "source_pages": [52, 53, 54, 55], "source_pdf_pages": [60, 61, 62, 63], "rpt_book_pages": "52, 53, 54, 55", "main_standard_key": "3.3.1", "sk_code": "3.3", "sk_text": "Melakukan senaman kelenturan dengan lakuan yang betul.", "sp_code": "3.3.1", "sp_text": "Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama.", "complementary_standards": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Gerakan bahu dan tangan serta regangan statik", "authoring_focus": "Gerakan bahu dan tangan serta regangan statik", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "RPT menumpukan dinamik BT52–53; BT54–55 ditambah bagi statik kerana SP3.3.1 merangkumi kedua-duanya. Teks DSKP menggunakan sendi-sendi utama, bukan salinan ayat RPT otot-otot utama. Dua pernyataan DSKP berkod 4.3.2 dikekalkan dengan penanda lokasi berasingan; kod RPT4.3.3 belum disahkan sebagai kod unik DSKP. Tujuan regangan tetap diajar tanpa membetulkan nombor secara senyap.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": true, "source_code_note": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP.", "unperformed_literal_elements": ["RPT4.3.3: padanan kod unik belum disahkan; tujuan diajar melalui pernyataan4.3.2 kedua yang tercetak."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas.", "Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat.", "Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur.", "Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Gerakkan bahu dan tangan, kemudian tahan regangan", "objective": "Murid dapat melakukan regangan dinamik dan statik dengan gerakan yang terkawal.", "success_criteria": ["Melakukan dua gerakan dinamik bahu dan tangan serta dua regangan statik yang ditunjukkan guru.", "Mengenal dinamik dan statik serta menyebut satu tujuan regangan."], "prior_knowledge": "Murid pernah menggerakkan tangan dan berjalan untuk pemanasan.", "equipment": [{"item": "Kon penanda", "quantity": "Empat kon di luar tempat pijakan.", "use": "Menandakan sempadan; bukan halangan untuk dilompat."}, {"item": "Jam guru dan buku teks", "quantity": "Satu jam; BT52–55 sebagai rujukan guru.", "use": "Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"item": "Air minuman sendiri", "quantity": "Satu botol setiap murid mengikut keperluan.", "use": "Rehat dan minum sebelum, semasa serta selepas aktiviti."}], "preparation": ["Tetapkan ruang sendiri yang cukup untuk mendepakan tangan tanpa bersentuh. Kon di luar pijakan.", "Pilih gerakan dinamik BT52: membuka dan merapatkan tangan serta rotasi bahu kecil.", "Gunakan regangan statik bahu secara silang dada dan betis sebagai contoh guru berpandukan kumpulan otot BT54–55; bukan mendakwa menyalin postur gambar."], "organisation": ["Murid berpasangan di ruang bersebelahan. Semasa latihan semua bergerak bersama; ketika semakan seorang bergerak, seorang melihat tanpa menyentuh.", "Setiap murid melakukan dinamik dan statik. Bantuan berlaku dalam masa yang sama, bukan satu jenis untuk satu kumpulan.", "Rehat dan air disediakan dalam setiap pertukaran; kurangkan ulangan jika masa atau kesediaan tidak mencukupi."], "movement_cues": ["Dinamik: berdiri selesa, buka tangan ke sisi setakat selesa dan rapatkan semula perlahan. Ulang empat kali sebagai cadangan guru.", "Gerakkan bahu membuat bulatan kecil ke belakang tanpa memusing leher atau mengangkat tangan tinggi.", "Statik bahu: bawa satu lengan merentas dada; tangan sendiri menyokong ringan lengan atas, bukan menekan siku. Tahan selesa, lepaskan dan tukar sisi.", "Statik betis: satu kaki kecil ke belakang, kedua-dua tapak menghadap depan; bengkokkan lutut depan sedikit dengan tumit belakang kekal di lantai. Tukar kaki.", "Dinamik mempunyai pergerakan terkawal; statik mengekalkan posisi seketika. Tujuannya membantu kelenturan dan gerakan sendi, bukan melatih sehingga sakit."], "timing_note": "Empat ulangan dinamik dan kira-kira 10 saat statik ialah cadangan guru mengikut kesediaan. Semua rehat dan peralihan termasuk dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Buka dan rapatkan tangan perlahan. Selepas itu, tahan lengan merentas dada dengan selesa. Mana satu bergerak dan mana satu ditahan?", "pupils_do": "Murid melakukan kedua-duanya dan menyebut dinamik bergerak, statik ditahan.", "teacher_checks": "Guru menyemak dua jenis lakuan dan jawapan sendiri, bukan menilai julat paling jauh."}, "bbm": ["Kon penanda — Empat kon di luar tempat pijakan.", "Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru.", "Air minuman sendiri — Satu botol setiap murid mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam guru dan buku teks", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Guru membezakan bergerak dan menahan", "minutes": 4, "teacher": ["Guru menunjukkan membuka/merapatkan tangan dan rotasi bahu kecil.", "Guru menunjukkan silang dada serta regangan betis pada kedua-dua sisi. Nyatakan tahan selesa tanpa menekan sendi."], "pupils": ["Murid meniru dengan julat kecil.", "Murid menyebut dinamik bagi gerakan dan statik bagi posisi yang ditahan."], "check": "Kedua-dua jenis diperkenalkan dengan teknik selamat.", "resources": ["Ruang sendiri", "Buku teks"]}, {"name": "Bahu dan tangan bergerak terkawal", "minutes": 9, "teacher": ["Gunakan tiga minit untuk dua gerakan dinamik dengan empat ulangan perlahan setiap satu dan rehat singkat.", "Gunakan satu minit untuk rehat serta minum jika perlu.", "Gunakan empat minit untuk silang dada dan regangan betis kiri/kanan, tahan kira-kira 10 saat jika selesa, kemudian lepaskan.", "Pada minit akhir, guru meminta beberapa murid menyebut tujuan regangan sambil berehat."], "pupils": ["Murid membuka/merapatkan tangan dan memutar bahu kecil.", "Murid berhenti untuk rehat dan memaklumkan ketidakselesaan.", "Murid menahan regangan bahu serta betis pada kedua-dua sisi tanpa bantuan tubuh pasangan."], "check": "Pemerhatian menjejak dinamik dan statik murid yang sama.", "resources": ["Jam guru", "Kon di tepi", "Air sendiri"]}, {"name": "Giliran tunjuk dua jenis", "minutes": 7, "teacher": ["Berikan dua minit kepada A dan dua minit kepada B untuk menunjukkan satu dinamik dan satu statik yang dipilih guru.", "Gunakan satu minit untuk rehat/minum dan dua minit untuk soalan jenis serta tujuan.", "Beri satu pembetulan seperti mengecilkan bulatan bahu; murid tidak perlu menambah julat."], "pupils": ["Murid menjalani giliran sendiri dan menunggu tanpa menyentuh rakan.", "Murid mengenal jenis gerakan serta menyebut tujuan dengan kata mudah.", "Murid memberi respons sebenar tentang aktiviti yang selesa atau tidak selesa."], "check": "Bukti lakuan dan jawapan sendiri direkod; murid belum dilihat ditanda susulan.", "resources": ["Jam guru", "Ruang sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Melakukan dinamik bahu dan tangan serta statik bahu dan betis dengan contoh dekat.", "materials": ["Ruang sendiri", "Kon di tepi"], "teacher": ["Guru menunjukkan satu gerakan pada satu masa dengan julat kecil.", "Beri pilihan dinamik atau statik dan kata bantu tujuan tanpa menarik anggota murid."], "pupil_steps": ["Buka dan rapatkan tangan perlahan serta buat rotasi bahu kecil.", "Lakukan silang dada dan regangan betis kiri/kanan dengan tahan singkat yang selesa.", "Sebut dinamik bergerak dan statik ditahan apabila guru bertanya.", "Nyatakan tujuan membantu kelenturan dan beritahu jika perlu rehat."], "product": "Dua jenis regangan sendiri serta respons jenis dan tujuan.", "criterion": "Dinamik dan statik dicuba dengan kawalan; tempoh pendek atau bantuan dicatat.", "next_step": "Ulang satu petunjuk tangan atau tumit dengan guru.", "example": {"teacher": "Gerakan tangan tadi dinamik atau statik?", "pupil": "Dinamik; tangan bergerak."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melakukan urutan bahu/tangan dinamik diikuti dua statik secara bergilir.", "materials": ["Ruang pasangan", "Jam guru"], "teacher": ["Semak kedua-dua sisi dan posisi tumit dari jarak selamat.", "Tanya jenis serta tujuan selepas murid berhenti."], "pupil_steps": ["Buka/rapatkan tangan dan rotasi bahu perlahan.", "Tahan silang dada serta regangan betis, kemudian tukar sisi.", "Tunjukkan satu dinamik dan satu statik pada giliran sendiri.", "Sebut tujuan membantu kelenturan dan satu cara mengelakkan sakit."], "product": "Urutan dinamik serta statik dan jawapan individu.", "criterion": "Kedua-dua jenis dan tujuan dikenal; tiada henjutan atau paksaan.", "next_step": "Perkemas satu posisi tanpa menambah masa tahan.", "example": {"teacher": "Apakah beza regangan statik?", "pupil": "Kita tahan posisi seketika tanpa henjutan."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas peralihan daripada dinamik bahu kepada statik yang selesa.", "materials": ["Ruang sendiri"], "teacher": ["Minta satu pembaikan kawalan sahaja.", "Jangan minta lebih lentur, lebih lama atau lebih cepat."], "pupil_steps": ["Lakukan dua dinamik dengan bahu santai.", "Berhenti sebelum memulakan silang dada dan regangan betis statik.", "Tukar sisi dengan tenang dan tunjuk kedua-dua jenis sendiri.", "Nyatakan tujuan regangan dan satu pembaikan kawalan yang dibuat."], "product": "Dua jenis regangan dan penerangan ringkas pembaikan.", "criterion": "Peralihan terkawal; jenis dan tujuan tetap dinilai.", "next_step": "Kekalkan julat yang selesa pada latihan seterusnya.", "example": {"teacher": "Apa yang kamu perkemas?", "pupil": "Saya kecilkan bulatan bahu dan berhenti sebelum menahan regangan."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan regangan dinamik dan statik dengan gerakan yang terkawal.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu contoh kecil Peneroka.", "Semak jenis dan teknik Pembina.", "Perkemas kawalan Pencabar tanpa menaikkan cabaran fizikal."], "individual_check": "Melakukan dua gerakan dinamik bahu dan tangan serta dua regangan statik yang ditunjukkan guru.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu semasa latihan dan giliran pasangan.", "evidence": "Lakuan dinamik dan statik bahu, tangan dan betis murid sendiri.", "criterion": "Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik: ____", "Statik: ____", "Kiri/kanan jika berkaitan: ____", "Bantuan / belum diperhatikan: ____"]}, "pbd_complementary": {"4.3.1": {"method": "Pemerhatian dan soalan ringkas tentang teknik.", "evidence": "Murid menunjukkan satu cara selamat ketika bahu, tangan dan betis.", "criterion": "Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Cara selamat ditunjukkan: ____", "Bantuan / belum dilihat: ____"]}, "PJ1-DSKP-P82-L16": {"method": "Soal jawab individu selepas bergerak.", "evidence": "Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan.", "criterion": "Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik dikenal: ____", "Statik dikenal: ____", "Bantuan: ____"]}, "PJ1-DSKP-P82-L18": {"method": "Soalan tujuan dengan kata mudah.", "evidence": "Murid menyebut tujuan regangan bagi bahu, tangan dan betis.", "criterion": "Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tujuan yang disebut: ____", "Kata bantu / belum didengar: ____"]}, "5.2.1": {"method": "Pemerhatian dan respons individu sepanjang latihan.", "evidence": "Respons murid tentang pengalaman regangan.", "criterion": "Catat respons sebenar tanpa memaksa murid tersenyum atau mengabaikan kesakitan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons atau tindakan sebenar: ____", "Bantuan / rehat / belum dilihat: ____"]}}, "intervention": ["Jika sakit atau julat sukar, hentikan dan gunakan gerakan lebih kecil selepas guru menilai.", "Ulang soalan dinamik, statik dan tujuan pada giliran susulan; kedua-dua rekod 4.3.2 tidak digabungkan."], "book_pages_text": "52, 53, 54, 55", "sp_focus": "", "sp_display": "3.3.1", "complementary": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "5c59f6d64119253bc359c1cf0f39fb20938937bca8092688393623f4e6c9da03"}'::jsonb,'[{"kind": "title", "text": "Minggu 35 Sesi 1 — Gerakkan bahu dan tangan, kemudian tahan regangan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W35-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Siap Siaga"}, {"kind": "p", "text": "Aktiviti guru: Gerakkan bahu dan tangan, kemudian tahan regangan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 52, 53, 54, 55."}, {"kind": "p", "text": "Empat ulangan dinamik dan kira-kira 10 saat statik ialah cadangan guru mengikut kesediaan. Semua rehat dan peralihan termasuk dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.3: Melakukan senaman kelenturan dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.3.1: Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.1: Mengenal pasti cara regangan yang betul."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Menyatakan tujuan melakukan senaman regangan."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "p", "text": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan regangan dinamik dan statik dengan gerakan yang terkawal."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan dua gerakan dinamik bahu dan tangan serta dua regangan statik yang ditunjukkan guru."}, {"kind": "p", "text": "2. Mengenal dinamik dan statik serta menyebut satu tujuan regangan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah menggerakkan tangan dan berjalan untuk pemanasan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan sempadan; bukan halangan untuk dilompat."}, {"kind": "label", "text": "Jam guru dan buku teks"}, {"kind": "p", "text": "Keperluan: Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "Kegunaan: Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Rehat dan minum sebelum, semasa serta selepas aktiviti."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Tetapkan ruang sendiri yang cukup untuk mendepakan tangan tanpa bersentuh. Kon di luar pijakan."}, {"kind": "p", "text": "2. Pilih gerakan dinamik BT52: membuka dan merapatkan tangan serta rotasi bahu kecil."}, {"kind": "p", "text": "3. Gunakan regangan statik bahu secara silang dada dan betis sebagai contoh guru berpandukan kumpulan otot BT54–55; bukan mendakwa menyalin postur gambar."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid berpasangan di ruang bersebelahan. Semasa latihan semua bergerak bersama; ketika semakan seorang bergerak, seorang melihat tanpa menyentuh."}, {"kind": "p", "text": "2. Setiap murid melakukan dinamik dan statik. Bantuan berlaku dalam masa yang sama, bukan satu jenis untuk satu kumpulan."}, {"kind": "p", "text": "3. Rehat dan air disediakan dalam setiap pertukaran; kurangkan ulangan jika masa atau kesediaan tidak mencukupi."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Dinamik: berdiri selesa, buka tangan ke sisi setakat selesa dan rapatkan semula perlahan. Ulang empat kali sebagai cadangan guru."}, {"kind": "p", "text": "2. Gerakkan bahu membuat bulatan kecil ke belakang tanpa memusing leher atau mengangkat tangan tinggi."}, {"kind": "p", "text": "3. Statik bahu: bawa satu lengan merentas dada; tangan sendiri menyokong ringan lengan atas, bukan menekan siku. Tahan selesa, lepaskan dan tukar sisi."}, {"kind": "p", "text": "4. Statik betis: satu kaki kecil ke belakang, kedua-dua tapak menghadap depan; bengkokkan lutut depan sedikit dengan tumit belakang kekal di lantai. Tukar kaki."}, {"kind": "p", "text": "5. Dinamik mempunyai pergerakan terkawal; statik mengekalkan posisi seketika. Tujuannya membantu kelenturan dan gerakan sendi, bukan melatih sehingga sakit."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "2. Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas."}, {"kind": "p", "text": "5. Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat."}, {"kind": "p", "text": "6. Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur."}, {"kind": "p", "text": "7. Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam guru dan buku teks Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Guru membezakan bergerak dan menahan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan membuka/merapatkan tangan dan rotasi bahu kecil."}, {"kind": "p", "text": "2. Guru menunjukkan silang dada serta regangan betis pada kedua-dua sisi. Nyatakan tahan selesa tanpa menekan sendi."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru dengan julat kecil."}, {"kind": "p", "text": "2. Murid menyebut dinamik bagi gerakan dan statik bagi posisi yang ditahan."}, {"kind": "p", "text": "Semakan: Kedua-dua jenis diperkenalkan dengan teknik selamat."}, {"kind": "p", "text": "Alatan: Ruang sendiri Buku teks"}, {"kind": "h3", "text": "Langkah 4: Bahu dan tangan bergerak terkawal — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan tiga minit untuk dua gerakan dinamik dengan empat ulangan perlahan setiap satu dan rehat singkat."}, {"kind": "p", "text": "2. Gunakan satu minit untuk rehat serta minum jika perlu."}, {"kind": "p", "text": "3. Gunakan empat minit untuk silang dada dan regangan betis kiri/kanan, tahan kira-kira 10 saat jika selesa, kemudian lepaskan."}, {"kind": "p", "text": "4. Pada minit akhir, guru meminta beberapa murid menyebut tujuan regangan sambil berehat."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membuka/merapatkan tangan dan memutar bahu kecil."}, {"kind": "p", "text": "2. Murid berhenti untuk rehat dan memaklumkan ketidakselesaan."}, {"kind": "p", "text": "3. Murid menahan regangan bahu serta betis pada kedua-dua sisi tanpa bantuan tubuh pasangan."}, {"kind": "p", "text": "Semakan: Pemerhatian menjejak dinamik dan statik murid yang sama."}, {"kind": "p", "text": "Alatan: Jam guru Kon di tepi Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Giliran tunjuk dua jenis — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Berikan dua minit kepada A dan dua minit kepada B untuk menunjukkan satu dinamik dan satu statik yang dipilih guru."}, {"kind": "p", "text": "2. Gunakan satu minit untuk rehat/minum dan dua minit untuk soalan jenis serta tujuan."}, {"kind": "p", "text": "3. Beri satu pembetulan seperti mengecilkan bulatan bahu; murid tidak perlu menambah julat."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjalani giliran sendiri dan menunggu tanpa menyentuh rakan."}, {"kind": "p", "text": "2. Murid mengenal jenis gerakan serta menyebut tujuan dengan kata mudah."}, {"kind": "p", "text": "3. Murid memberi respons sebenar tentang aktiviti yang selesa atau tidak selesa."}, {"kind": "p", "text": "Semakan: Bukti lakuan dan jawapan sendiri direkod; murid belum dilihat ditanda susulan."}, {"kind": "p", "text": "Alatan: Jam guru Ruang sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Buka dan rapatkan tangan perlahan. Selepas itu, tahan lengan merentas dada dengan selesa. Mana satu bergerak dan mana satu ditahan?"}, {"kind": "p", "text": "Murid: Murid melakukan kedua-duanya dan menyebut dinamik bergerak, statik ditahan."}, {"kind": "p", "text": "Semakan guru: Guru menyemak dua jenis lakuan dan jawapan sendiri, bukan menilai julat paling jauh."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W35-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan regangan dinamik dan statik dengan gerakan yang terkawal."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu contoh kecil Peneroka."}, {"kind": "p", "text": "2. Semak jenis dan teknik Pembina."}, {"kind": "p", "text": "3. Perkemas kawalan Pencabar tanpa menaikkan cabaran fizikal."}, {"kind": "p", "text": "Semakan individu: Melakukan dua gerakan dinamik bahu dan tangan serta dua regangan statik yang ditunjukkan guru."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Melakukan dinamik bahu dan tangan serta statik bahu dan betis dengan contoh dekat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "p", "text": "2. Kon di tepi"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan satu gerakan pada satu masa dengan julat kecil."}, {"kind": "p", "text": "2. Beri pilihan dinamik atau statik dan kata bantu tujuan tanpa menarik anggota murid."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Buka dan rapatkan tangan perlahan serta buat rotasi bahu kecil."}, {"kind": "p", "text": "2. Lakukan silang dada dan regangan betis kiri/kanan dengan tahan singkat yang selesa."}, {"kind": "p", "text": "3. Sebut dinamik bergerak dan statik ditahan apabila guru bertanya."}, {"kind": "p", "text": "4. Nyatakan tujuan membantu kelenturan dan beritahu jika perlu rehat."}, {"kind": "p", "text": "Contoh guru: Gerakan tangan tadi dinamik atau statik?"}, {"kind": "p", "text": "Contoh respons murid: Dinamik; tangan bergerak."}, {"kind": "p", "text": "Hasil individu: Dua jenis regangan sendiri serta respons jenis dan tujuan."}, {"kind": "p", "text": "Kriteria: Dinamik dan statik dicuba dengan kawalan; tempoh pendek atau bantuan dicatat."}, {"kind": "p", "text": "Susulan: Ulang satu petunjuk tangan atau tumit dengan guru."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melakukan urutan bahu/tangan dinamik diikuti dua statik secara bergilir."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan"}, {"kind": "p", "text": "2. Jam guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak kedua-dua sisi dan posisi tumit dari jarak selamat."}, {"kind": "p", "text": "2. Tanya jenis serta tujuan selepas murid berhenti."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Buka/rapatkan tangan dan rotasi bahu perlahan."}, {"kind": "p", "text": "2. Tahan silang dada serta regangan betis, kemudian tukar sisi."}, {"kind": "p", "text": "3. Tunjukkan satu dinamik dan satu statik pada giliran sendiri."}, {"kind": "p", "text": "4. Sebut tujuan membantu kelenturan dan satu cara mengelakkan sakit."}, {"kind": "p", "text": "Contoh guru: Apakah beza regangan statik?"}, {"kind": "p", "text": "Contoh respons murid: Kita tahan posisi seketika tanpa henjutan."}, {"kind": "p", "text": "Hasil individu: Urutan dinamik serta statik dan jawapan individu."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dan tujuan dikenal; tiada henjutan atau paksaan."}, {"kind": "p", "text": "Susulan: Perkemas satu posisi tanpa menambah masa tahan."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas peralihan daripada dinamik bahu kepada statik yang selesa."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minta satu pembaikan kawalan sahaja."}, {"kind": "p", "text": "2. Jangan minta lebih lentur, lebih lama atau lebih cepat."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dua dinamik dengan bahu santai."}, {"kind": "p", "text": "2. Berhenti sebelum memulakan silang dada dan regangan betis statik."}, {"kind": "p", "text": "3. Tukar sisi dengan tenang dan tunjuk kedua-dua jenis sendiri."}, {"kind": "p", "text": "4. Nyatakan tujuan regangan dan satu pembaikan kawalan yang dibuat."}, {"kind": "p", "text": "Contoh guru: Apa yang kamu perkemas?"}, {"kind": "p", "text": "Contoh respons murid: Saya kecilkan bulatan bahu dan berhenti sebelum menahan regangan."}, {"kind": "p", "text": "Hasil individu: Dua jenis regangan dan penerangan ringkas pembaikan."}, {"kind": "p", "text": "Kriteria: Peralihan terkawal; jenis dan tujuan tetap dinilai."}, {"kind": "p", "text": "Susulan: Kekalkan julat yang selesa pada latihan seterusnya."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu semasa latihan dan giliran pasangan."}, {"kind": "p", "text": "Bukti: Lakuan dinamik dan statik bahu, tangan dan betis murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik: ____"}, {"kind": "p", "text": "2. Statik: ____"}, {"kind": "p", "text": "3. Kiri/kanan jika berkaitan: ____"}, {"kind": "p", "text": "4. Bantuan / belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan soalan ringkas tentang teknik."}, {"kind": "p", "text": "Bukti: Murid menunjukkan satu cara selamat ketika bahu, tangan dan betis."}, {"kind": "p", "text": "Kriteria: Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Cara selamat ditunjukkan: ____"}, {"kind": "p", "text": "2. Bantuan / belum dilihat: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas bergerak."}, {"kind": "p", "text": "Bukti: Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik dikenal: ____"}, {"kind": "p", "text": "2. Statik dikenal: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "Kaedah: Soalan tujuan dengan kata mudah."}, {"kind": "p", "text": "Bukti: Murid menyebut tujuan regangan bagi bahu, tangan dan betis."}, {"kind": "p", "text": "Kriteria: Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tujuan yang disebut: ____"}, {"kind": "p", "text": "2. Kata bantu / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan respons individu sepanjang latihan."}, {"kind": "p", "text": "Bukti: Respons murid tentang pengalaman regangan."}, {"kind": "p", "text": "Kriteria: Catat respons sebenar tanpa memaksa murid tersenyum atau mengabaikan kesakitan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons atau tindakan sebenar: ____"}, {"kind": "p", "text": "2. Bantuan / rehat / belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika sakit atau julat sukar, hentikan dan gunakan gerakan lebih kecil selepas guru menilai."}, {"kind": "p", "text": "2. Ulang soalan dinamik, statik dan tujuan pada giliran susulan; kedua-dua rekod 4.3.2 tidak digabungkan."}]'::jsonb,'{"source_hold": "", "adaptation_note": "RPT menumpukan dinamik BT52–53; BT54–55 ditambah bagi statik kerana SP3.3.1 merangkumi kedua-duanya. Teks DSKP menggunakan sendi-sendi utama, bukan salinan ayat RPT otot-otot utama. Dua pernyataan DSKP berkod 4.3.2 dikekalkan dengan penanda lokasi berasingan; kod RPT4.3.3 belum disahkan sebagai kod unik DSKP. Tujuan regangan tetap diajar tanpa membetulkan nombor secara senyap.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W35-S2','pj',1,2026,35,2,30,'3.3.1',array[52,53,54,55]::int[],'f8e9dc952fce23122a1695cd618f53f972f7d78836496414a0fadcd26f79959f','861bbf2bb78f36e28486cd703c1bbcc2cba148d15d08c02d859b9bb4c86f4931','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W35-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 35, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Siap Siaga", "source_title": "Siap Siaga", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T12-R3", "source_row_literal": ["35\n\nKump A: 04.10.2026-08.10.2026\n\nKump B: 05.10.2026- 09.10.2026", "8: CERGAS DAN MANTAP\n\nSIAP SIAGA", "3.3 Melakukan senaman kelenturan dengan lakuan yang betul.\n4.3 Mengaplikasi konsep asas kelenturan\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "3.3.1  Melakukan aktiviti regangan dinamik dan statik pada otot-otot utama.\n\n4.3.1 Mengenal pasti cara regangan yang betul.\n4.3.2  Mengenali pelbagai pergerakan \nyang betul untuk meningkatkan \nkelenturan pada sesuatu kumpulan \notot.\n4.3.3  Mengetahui bahawa aktiviti \nregangan dapat meningkatkan \nkecekapan fungsi otot.\n\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\nPermainan kecil:\nRegangan rahsia\n\nBT m/s 52-53"], "rpt_original_page_literal": "52-53", "source_pages": [52, 53, 54, 55], "source_pdf_pages": [60, 61, 62, 63], "rpt_book_pages": "52, 53, 54, 55", "main_standard_key": "3.3.1", "sk_code": "3.3", "sk_text": "Melakukan senaman kelenturan dengan lakuan yang betul.", "sp_code": "3.3.1", "sp_text": "Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama.", "complementary_standards": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Gerakan lutut dan langkah serta regangan statik", "authoring_focus": "Gerakan lutut dan langkah serta regangan statik", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "RPT menumpukan dinamik BT52–53; BT54–55 ditambah bagi statik kerana SP3.3.1 merangkumi kedua-duanya. Teks DSKP menggunakan sendi-sendi utama, bukan salinan ayat RPT otot-otot utama. Dua pernyataan DSKP berkod 4.3.2 dikekalkan dengan penanda lokasi berasingan; kod RPT4.3.3 belum disahkan sebagai kod unik DSKP. Tujuan regangan tetap diajar tanpa membetulkan nombor secara senyap.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": true, "source_code_note": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP.", "unperformed_literal_elements": ["RPT4.3.3: padanan kod unik belum disahkan; tujuan diajar melalui pernyataan4.3.2 kedua yang tercetak."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas.", "Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat.", "Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur.", "Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Gerakkan lutut dan kaki, kemudian regangkan betis", "objective": "Murid dapat melakukan regangan dinamik dan statik pada bahagian kaki serta badan dengan selamat.", "success_criteria": ["Melakukan gerakan dinamik lutut dan kaki serta regangan statik betis dan belakang atas.", "Mengenal kedua-dua jenis serta menyebut satu tujuan regangan."], "prior_knowledge": "Murid pernah membezakan gerakan dinamik dengan posisi statik; contoh diulang sebelum mencuba.", "equipment": [{"item": "Kon penanda", "quantity": "Empat kon di luar tempat pijakan.", "use": "Menandakan sempadan; bukan halangan untuk dilompat."}, {"item": "Jam guru dan buku teks", "quantity": "Satu jam; BT52–55 sebagai rujukan guru.", "use": "Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"item": "Air minuman sendiri", "quantity": "Satu botol setiap murid mengikut keperluan.", "use": "Rehat dan minum sebelum, semasa serta selepas aktiviti."}], "preparation": ["Pastikan ruang kaki bebas daripada botol dan kon. Guru menunjukkan kaki bergerak dekat lantai, bukan tendangan tinggi.", "Pilih fleksi dan ekstensi lutut serta ayunan kaki kecil berpandukan nama gerakan BT52–53.", "Regangan statik betis dan belakang atas menjadi contoh guru bagi kumpulan otot BT54; semua dalam julat selesa."], "organisation": ["Murid berdiri bersebelahan pasangan, tidak berpegangan untuk menarik badan.", "Kedua-dua murid melakukan dinamik dan statik dalam latihan. Semakan bergilir membolehkan guru melihat tindakan sendiri.", "Jika imbangan sukar, ganti ayunan dengan sentuhan hujung kaki ke depan dan belakang yang rendah; catat penyesuaian."], "movement_cues": ["Berdiri kaki selesa. Bengkokkan kedua-dua lutut sedikit, kemudian luruskan tanpa mengunci lutut.", "Alih berat ke satu kaki dan gerakkan kaki sebelah sedikit ke depan dan belakang dekat lantai. Gunakan sentuhan hujung kaki jika perlu, kemudian tukar kaki.", "Statik betis: satu kaki ke belakang, tumit di lantai dan lutut depan sedikit bengkok. Tahan selesa lalu tukar sisi.", "Statik belakang atas: hulurkan kedua-dua tangan ke depan, rapatkan tangan dan bulatkan belakang atas sedikit. Bahu tidak dinaikkan dan pinggang tidak dilentik.", "Dinamik ialah bergerak terkawal; statik menahan posisi seketika. Regangan membantu kelenturan sendi dan gerakan, bukan alasan meneruskan jika sakit."], "timing_note": "Cadangan empat ulangan perlahan setiap dinamik dan tahan statik sekitar 10 saat; rehat atau lepaskan lebih awal jika perlu. Jumlah sesi kekal 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Bengkok sedikit dan luruskan lutut. Sekarang berhenti dan regangkan betis. Mana satu dinamik?", "pupils_do": "Murid memilih gerakan lutut sebagai dinamik dan menunjukkan statik betis.", "teacher_checks": "Guru semak lutut tidak dikunci, tumit kekal dan jawapan jenis tepat."}, "bbm": ["Kon penanda — Empat kon di luar tempat pijakan.", "Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru.", "Air minuman sendiri — Satu botol setiap murid mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam guru dan buku teks", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Lutut bergerak, betis ditahan", "minutes": 4, "teacher": ["Guru menunjukkan fleksi lutut kecil dan gerakan kaki rendah.", "Guru menunjukkan statik betis serta tangan ke depan untuk belakang atas. Ingatkan nafas biasa."], "pupils": ["Murid meniru satu contoh dengan julat kecil.", "Murid menyebut dinamik atau statik bagi dua contoh guru."], "check": "Perbezaan lakuan dikenal tanpa tekanan pasangan.", "resources": ["Ruang rata"]}, {"name": "Latihan kaki dan belakang atas", "minutes": 9, "teacher": ["Gunakan tiga minit untuk fleksi lutut dan ayunan kecil atau sentuhan kaki, kedua-dua sisi.", "Beri satu minit rehat dan minum.", "Gunakan empat minit untuk statik betis kiri/kanan dan belakang atas dengan pelepasan antara tahan.", "Pada minit akhir, tanya tujuan serta semak murid yang meminta bantuan imbangan."], "pupils": ["Murid membengkok dan meluruskan lutut sedikit.", "Murid menggerakkan kaki rendah atau menggunakan penyesuaian sentuhan kaki.", "Murid melakukan betis statik dan tangan ke depan tanpa memaksa badan."], "check": "Guru melihat kedua-dua jenis; penyesuaian imbangan dicatat.", "resources": ["Kon di tepi", "Jam", "Air sendiri"]}, {"name": "Pilih dan tunjuk regangan", "minutes": 7, "teacher": ["Beri dua minit kepada A dan dua minit kepada B untuk menunjukkan satu dinamik kaki dan dua statik yang telah diajar.", "Sediakan satu minit rehat serta dua minit soalan jenis dan tujuan.", "Minta murid menyebut pergerakan yang selesa tanpa memaksa respons seronok."], "pupils": ["Murid melakukan giliran sendiri.", "Murid yang menunggu memberi ruang dan tidak menolak lutut atau belakang rakan.", "Murid mengenal dinamik/statik dan menyebut tujuan dengan bantuan kata jika perlu."], "check": "Dua rekod 4.3.2 dinilai berasingan: jenis dan tujuan.", "resources": ["Ruang sendiri", "Senarai guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Melakukan dinamik lutut/kaki dan statik betis/belakang atas dengan contoh guru.", "materials": ["Ruang sendiri"], "teacher": ["Gunakan sentuhan kaki ke lantai jika imbangan sukar.", "Beri kata mula dinamik bergerak dan statik tahan; jangan memaksa lutut membengkok jauh."], "pupil_steps": ["Bengkok dan luruskan lutut sedikit serta sentuh kaki ke depan-belakang.", "Tahan regangan betis kiri/kanan dan hulur tangan ke depan bagi statik belakang atas.", "Sebut jenis dinamik dan statik selepas berhenti.", "Nyatakan tujuan membantu kelenturan dan beritahu jika perlu rehat."], "product": "Dinamik dan statik individu serta dua respons mudah.", "criterion": "Kedua-dua jenis dicuba selamat; penyesuaian dicatat.", "next_step": "Ulang satu gerakan rendah sebelum cuba ayunan lagi.", "example": {"teacher": "Mengapa kita regang?", "pupil": "Untuk membantu badan dan sendi bergerak dengan selesa."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mengawal gerakan kaki kemudian mengekalkan statik dengan selesa.", "materials": ["Ruang pasangan"], "teacher": ["Semak tumit belakang dan bahu santai melalui contoh semula.", "Tanya tujuan selepas murid menunjukkan kedua-dua jenis."], "pupil_steps": ["Lakukan fleksi lutut dan ayunan kaki kecil pada dua sisi.", "Lakukan statik betis serta belakang atas dengan pelepasan antara tahan.", "Tunjukkan satu dinamik dan satu statik pada giliran sendiri.", "Sebut tujuan dan satu cara selamat seperti tidak menghenjut."], "product": "Urutan kaki dan badan serta jawapan sendiri.", "criterion": "Dinamik/statik dibezakan dan tujuan disebut tanpa mengabaikan keselesaan.", "next_step": "Perkemas posisi tumit dengan jarak kaki yang lebih kecil jika perlu.", "example": {"teacher": "Bagaimana tumit semasa regangan betis?", "pupil": "Tumit belakang kekal di lantai."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas imbangan semasa dinamik dan kawalan semasa statik.", "materials": ["Ruang sendiri"], "teacher": ["Kekalkan julat kecil dan masa yang sama.", "Minta satu pembaikan seperti kaki tidak bersilang, bukan menambah ayunan."], "pupil_steps": ["Lakukan dinamik lutut dan kaki rendah dengan nafas biasa.", "Berhenti sebelum bertukar kepada statik betis dan belakang atas.", "Tukar sisi dengan tenang dan lepaskan regangan tanpa sentapan.", "Sebut dinamik, statik serta tujuan membantu kelenturan."], "product": "Dua jenis dengan satu pembaikan kawalan individu.", "criterion": "Kawalan diperbaik tanpa menambah kelajuan atau julat.", "next_step": "Teruskan bantuan jika imbangan belum stabil.", "example": {"teacher": "Apa yang kamu perkemas?", "pupil": "Saya kecilkan langkah supaya boleh berhenti dengan stabil."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan regangan dinamik dan statik pada bahagian kaki serta badan dengan selamat.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu sentuhan kaki Peneroka.", "Semak statik Pembina.", "Dengar pembaikan kawalan Pencabar."], "individual_check": "Melakukan gerakan dinamik lutut dan kaki serta regangan statik betis dan belakang atas.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu semasa latihan dan giliran pasangan.", "evidence": "Lakuan dinamik dan statik lutut, kaki, betis dan belakang atas murid sendiri.", "criterion": "Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik: ____", "Statik: ____", "Kiri/kanan jika berkaitan: ____", "Bantuan / belum diperhatikan: ____"]}, "pbd_complementary": {"4.3.1": {"method": "Pemerhatian dan soalan ringkas tentang teknik.", "evidence": "Murid menunjukkan satu cara selamat ketika lutut, kaki, betis dan belakang atas.", "criterion": "Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Cara selamat ditunjukkan: ____", "Bantuan / belum dilihat: ____"]}, "PJ1-DSKP-P82-L16": {"method": "Soal jawab individu selepas bergerak.", "evidence": "Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan.", "criterion": "Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik dikenal: ____", "Statik dikenal: ____", "Bantuan: ____"]}, "PJ1-DSKP-P82-L18": {"method": "Soalan tujuan dengan kata mudah.", "evidence": "Murid menyebut tujuan regangan bagi lutut, kaki, betis dan belakang atas.", "criterion": "Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tujuan yang disebut: ____", "Kata bantu / belum didengar: ____"]}, "5.2.1": {"method": "Pemerhatian dan respons individu sepanjang latihan.", "evidence": "Respons murid tentang pengalaman regangan.", "criterion": "Catat respons sebenar tanpa memaksa murid tersenyum atau mengabaikan kesakitan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons atau tindakan sebenar: ____", "Bantuan / rehat / belum dilihat: ____"]}}, "intervention": ["Gunakan sentuhan kaki rendah jika ayunan menjejaskan imbangan.", "Rekod bahagian yang belum diperhatikan untuk susulan, bukan memaksa ulangan ketika letih."], "book_pages_text": "52, 53, 54, 55", "sp_focus": "", "sp_display": "3.3.1", "complementary": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "a4bd2cd947a93b3d37bfaf3255a37da47a846e8bfe1cc719449e59220e8d90e8"}'::jsonb,'[{"kind": "title", "text": "Minggu 35 Sesi 2 — Gerakkan lutut dan kaki, kemudian regangkan betis"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W35-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Siap Siaga"}, {"kind": "p", "text": "Aktiviti guru: Gerakkan lutut dan kaki, kemudian regangkan betis"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 52, 53, 54, 55."}, {"kind": "p", "text": "Cadangan empat ulangan perlahan setiap dinamik dan tahan statik sekitar 10 saat; rehat atau lepaskan lebih awal jika perlu. Jumlah sesi kekal 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.3: Melakukan senaman kelenturan dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.3.1: Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.1: Mengenal pasti cara regangan yang betul."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Menyatakan tujuan melakukan senaman regangan."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "p", "text": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan regangan dinamik dan statik pada bahagian kaki serta badan dengan selamat."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan gerakan dinamik lutut dan kaki serta regangan statik betis dan belakang atas."}, {"kind": "p", "text": "2. Mengenal kedua-dua jenis serta menyebut satu tujuan regangan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah membezakan gerakan dinamik dengan posisi statik; contoh diulang sebelum mencuba."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan sempadan; bukan halangan untuk dilompat."}, {"kind": "label", "text": "Jam guru dan buku teks"}, {"kind": "p", "text": "Keperluan: Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "Kegunaan: Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Rehat dan minum sebelum, semasa serta selepas aktiviti."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Pastikan ruang kaki bebas daripada botol dan kon. Guru menunjukkan kaki bergerak dekat lantai, bukan tendangan tinggi."}, {"kind": "p", "text": "2. Pilih fleksi dan ekstensi lutut serta ayunan kaki kecil berpandukan nama gerakan BT52–53."}, {"kind": "p", "text": "3. Regangan statik betis dan belakang atas menjadi contoh guru bagi kumpulan otot BT54; semua dalam julat selesa."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid berdiri bersebelahan pasangan, tidak berpegangan untuk menarik badan."}, {"kind": "p", "text": "2. Kedua-dua murid melakukan dinamik dan statik dalam latihan. Semakan bergilir membolehkan guru melihat tindakan sendiri."}, {"kind": "p", "text": "3. Jika imbangan sukar, ganti ayunan dengan sentuhan hujung kaki ke depan dan belakang yang rendah; catat penyesuaian."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Berdiri kaki selesa. Bengkokkan kedua-dua lutut sedikit, kemudian luruskan tanpa mengunci lutut."}, {"kind": "p", "text": "2. Alih berat ke satu kaki dan gerakkan kaki sebelah sedikit ke depan dan belakang dekat lantai. Gunakan sentuhan hujung kaki jika perlu, kemudian tukar kaki."}, {"kind": "p", "text": "3. Statik betis: satu kaki ke belakang, tumit di lantai dan lutut depan sedikit bengkok. Tahan selesa lalu tukar sisi."}, {"kind": "p", "text": "4. Statik belakang atas: hulurkan kedua-dua tangan ke depan, rapatkan tangan dan bulatkan belakang atas sedikit. Bahu tidak dinaikkan dan pinggang tidak dilentik."}, {"kind": "p", "text": "5. Dinamik ialah bergerak terkawal; statik menahan posisi seketika. Regangan membantu kelenturan sendi dan gerakan, bukan alasan meneruskan jika sakit."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "2. Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas."}, {"kind": "p", "text": "5. Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat."}, {"kind": "p", "text": "6. Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur."}, {"kind": "p", "text": "7. Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam guru dan buku teks Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Lutut bergerak, betis ditahan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan fleksi lutut kecil dan gerakan kaki rendah."}, {"kind": "p", "text": "2. Guru menunjukkan statik betis serta tangan ke depan untuk belakang atas. Ingatkan nafas biasa."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru satu contoh dengan julat kecil."}, {"kind": "p", "text": "2. Murid menyebut dinamik atau statik bagi dua contoh guru."}, {"kind": "p", "text": "Semakan: Perbezaan lakuan dikenal tanpa tekanan pasangan."}, {"kind": "p", "text": "Alatan: Ruang rata"}, {"kind": "h3", "text": "Langkah 4: Latihan kaki dan belakang atas — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan tiga minit untuk fleksi lutut dan ayunan kecil atau sentuhan kaki, kedua-dua sisi."}, {"kind": "p", "text": "2. Beri satu minit rehat dan minum."}, {"kind": "p", "text": "3. Gunakan empat minit untuk statik betis kiri/kanan dan belakang atas dengan pelepasan antara tahan."}, {"kind": "p", "text": "4. Pada minit akhir, tanya tujuan serta semak murid yang meminta bantuan imbangan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membengkok dan meluruskan lutut sedikit."}, {"kind": "p", "text": "2. Murid menggerakkan kaki rendah atau menggunakan penyesuaian sentuhan kaki."}, {"kind": "p", "text": "3. Murid melakukan betis statik dan tangan ke depan tanpa memaksa badan."}, {"kind": "p", "text": "Semakan: Guru melihat kedua-dua jenis; penyesuaian imbangan dicatat."}, {"kind": "p", "text": "Alatan: Kon di tepi Jam Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Pilih dan tunjuk regangan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit kepada A dan dua minit kepada B untuk menunjukkan satu dinamik kaki dan dua statik yang telah diajar."}, {"kind": "p", "text": "2. Sediakan satu minit rehat serta dua minit soalan jenis dan tujuan."}, {"kind": "p", "text": "3. Minta murid menyebut pergerakan yang selesa tanpa memaksa respons seronok."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan giliran sendiri."}, {"kind": "p", "text": "2. Murid yang menunggu memberi ruang dan tidak menolak lutut atau belakang rakan."}, {"kind": "p", "text": "3. Murid mengenal dinamik/statik dan menyebut tujuan dengan bantuan kata jika perlu."}, {"kind": "p", "text": "Semakan: Dua rekod 4.3.2 dinilai berasingan: jenis dan tujuan."}, {"kind": "p", "text": "Alatan: Ruang sendiri Senarai guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Bengkok sedikit dan luruskan lutut. Sekarang berhenti dan regangkan betis. Mana satu dinamik?"}, {"kind": "p", "text": "Murid: Murid memilih gerakan lutut sebagai dinamik dan menunjukkan statik betis."}, {"kind": "p", "text": "Semakan guru: Guru semak lutut tidak dikunci, tumit kekal dan jawapan jenis tepat."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W35-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan regangan dinamik dan statik pada bahagian kaki serta badan dengan selamat."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu sentuhan kaki Peneroka."}, {"kind": "p", "text": "2. Semak statik Pembina."}, {"kind": "p", "text": "3. Dengar pembaikan kawalan Pencabar."}, {"kind": "p", "text": "Semakan individu: Melakukan gerakan dinamik lutut dan kaki serta regangan statik betis dan belakang atas."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Melakukan dinamik lutut/kaki dan statik betis/belakang atas dengan contoh guru."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan sentuhan kaki ke lantai jika imbangan sukar."}, {"kind": "p", "text": "2. Beri kata mula dinamik bergerak dan statik tahan; jangan memaksa lutut membengkok jauh."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bengkok dan luruskan lutut sedikit serta sentuh kaki ke depan-belakang."}, {"kind": "p", "text": "2. Tahan regangan betis kiri/kanan dan hulur tangan ke depan bagi statik belakang atas."}, {"kind": "p", "text": "3. Sebut jenis dinamik dan statik selepas berhenti."}, {"kind": "p", "text": "4. Nyatakan tujuan membantu kelenturan dan beritahu jika perlu rehat."}, {"kind": "p", "text": "Contoh guru: Mengapa kita regang?"}, {"kind": "p", "text": "Contoh respons murid: Untuk membantu badan dan sendi bergerak dengan selesa."}, {"kind": "p", "text": "Hasil individu: Dinamik dan statik individu serta dua respons mudah."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dicuba selamat; penyesuaian dicatat."}, {"kind": "p", "text": "Susulan: Ulang satu gerakan rendah sebelum cuba ayunan lagi."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mengawal gerakan kaki kemudian mengekalkan statik dengan selesa."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak tumit belakang dan bahu santai melalui contoh semula."}, {"kind": "p", "text": "2. Tanya tujuan selepas murid menunjukkan kedua-dua jenis."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan fleksi lutut dan ayunan kaki kecil pada dua sisi."}, {"kind": "p", "text": "2. Lakukan statik betis serta belakang atas dengan pelepasan antara tahan."}, {"kind": "p", "text": "3. Tunjukkan satu dinamik dan satu statik pada giliran sendiri."}, {"kind": "p", "text": "4. Sebut tujuan dan satu cara selamat seperti tidak menghenjut."}, {"kind": "p", "text": "Contoh guru: Bagaimana tumit semasa regangan betis?"}, {"kind": "p", "text": "Contoh respons murid: Tumit belakang kekal di lantai."}, {"kind": "p", "text": "Hasil individu: Urutan kaki dan badan serta jawapan sendiri."}, {"kind": "p", "text": "Kriteria: Dinamik/statik dibezakan dan tujuan disebut tanpa mengabaikan keselesaan."}, {"kind": "p", "text": "Susulan: Perkemas posisi tumit dengan jarak kaki yang lebih kecil jika perlu."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas imbangan semasa dinamik dan kawalan semasa statik."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Kekalkan julat kecil dan masa yang sama."}, {"kind": "p", "text": "2. Minta satu pembaikan seperti kaki tidak bersilang, bukan menambah ayunan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dinamik lutut dan kaki rendah dengan nafas biasa."}, {"kind": "p", "text": "2. Berhenti sebelum bertukar kepada statik betis dan belakang atas."}, {"kind": "p", "text": "3. Tukar sisi dengan tenang dan lepaskan regangan tanpa sentapan."}, {"kind": "p", "text": "4. Sebut dinamik, statik serta tujuan membantu kelenturan."}, {"kind": "p", "text": "Contoh guru: Apa yang kamu perkemas?"}, {"kind": "p", "text": "Contoh respons murid: Saya kecilkan langkah supaya boleh berhenti dengan stabil."}, {"kind": "p", "text": "Hasil individu: Dua jenis dengan satu pembaikan kawalan individu."}, {"kind": "p", "text": "Kriteria: Kawalan diperbaik tanpa menambah kelajuan atau julat."}, {"kind": "p", "text": "Susulan: Teruskan bantuan jika imbangan belum stabil."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu semasa latihan dan giliran pasangan."}, {"kind": "p", "text": "Bukti: Lakuan dinamik dan statik lutut, kaki, betis dan belakang atas murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik: ____"}, {"kind": "p", "text": "2. Statik: ____"}, {"kind": "p", "text": "3. Kiri/kanan jika berkaitan: ____"}, {"kind": "p", "text": "4. Bantuan / belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan soalan ringkas tentang teknik."}, {"kind": "p", "text": "Bukti: Murid menunjukkan satu cara selamat ketika lutut, kaki, betis dan belakang atas."}, {"kind": "p", "text": "Kriteria: Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Cara selamat ditunjukkan: ____"}, {"kind": "p", "text": "2. Bantuan / belum dilihat: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas bergerak."}, {"kind": "p", "text": "Bukti: Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik dikenal: ____"}, {"kind": "p", "text": "2. Statik dikenal: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "Kaedah: Soalan tujuan dengan kata mudah."}, {"kind": "p", "text": "Bukti: Murid menyebut tujuan regangan bagi lutut, kaki, betis dan belakang atas."}, {"kind": "p", "text": "Kriteria: Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tujuan yang disebut: ____"}, {"kind": "p", "text": "2. Kata bantu / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan respons individu sepanjang latihan."}, {"kind": "p", "text": "Bukti: Respons murid tentang pengalaman regangan."}, {"kind": "p", "text": "Kriteria: Catat respons sebenar tanpa memaksa murid tersenyum atau mengabaikan kesakitan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons atau tindakan sebenar: ____"}, {"kind": "p", "text": "2. Bantuan / rehat / belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Gunakan sentuhan kaki rendah jika ayunan menjejaskan imbangan."}, {"kind": "p", "text": "2. Rekod bahagian yang belum diperhatikan untuk susulan, bukan memaksa ulangan ketika letih."}]'::jsonb,'{"source_hold": "", "adaptation_note": "RPT menumpukan dinamik BT52–53; BT54–55 ditambah bagi statik kerana SP3.3.1 merangkumi kedua-duanya. Teks DSKP menggunakan sendi-sendi utama, bukan salinan ayat RPT otot-otot utama. Dua pernyataan DSKP berkod 4.3.2 dikekalkan dengan penanda lokasi berasingan; kod RPT4.3.3 belum disahkan sebagai kod unik DSKP. Tujuan regangan tetap diajar tanpa membetulkan nombor secara senyap.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W36-S1','pj',1,2026,36,1,30,'3.3.1',array[52,53,54,55]::int[],'dbe4d76ff578debc01a6f5487d9a4fc1f93618ed8d8e1eda1d08eb30095be462','aecc78c197bbb061b25a2de462275c822e0ad7ea9ddb78b7c4fa68fe57af4156','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W36-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 36, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Tenang-tenang", "source_title": "Tenang-tenang", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T13-R2", "source_row_literal": ["36\n\nKump A: 11.10.2026-15.10.2026\n\nKump B:\n12.10.2026-16.10.2026", "8: CERGAS DAN MANTAP\n\nTENANG-TENANG", "3.3 Melakukan senaman kelenturan dengan lakuan yang betul.\n4.3 Mengaplikasi konsep asas kelenturan\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.3.1  Melakukan aktiviti regangan dinamik dan statik pada otot-otot utama.\n\n4.3.1 Mengenal pasti cara regangan yang betul.\n\n4.3.2  Mengenali pelbagai pergerakan yang betul untuk meningkatkan kelenturan pada sesuatu kumpulan otot.\n\n4.3.3  Mengetahui bahawa aktiviti regangan dapat meningkatkan kecekapan fungsi otot.\n\n5.1.3  Mematuhi arahan guru dan mengenal peraturan keselamatan di tempat melakukan aktiviti.", "Pemerhatian /\nPentaksiran\n\nPermainan kecil:\nRegangan rahsia\n\n\nBT m/s 54-55"], "rpt_original_page_literal": "54-55", "source_pages": [52, 53, 54, 55], "source_pdf_pages": [60, 61, 62, 63], "rpt_book_pages": "52, 53, 54, 55", "main_standard_key": "3.3.1", "sk_code": "3.3", "sk_text": "Melakukan senaman kelenturan dengan lakuan yang betul.", "sp_code": "3.3.1", "sp_text": "Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama.", "complementary_standards": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Regangan dinamik diikuti regangan betis dan paha", "authoring_focus": "Regangan dinamik diikuti regangan betis dan paha", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "RPT menumpukan statik BT54–55; dinamik BT52–53 digunakan dalam sesi juga. Dua pernyataan 4.3.2 tercetak dikekalkan; nombor RPT4.3.3 ditanda konflik. Regangan lembut kiri/kanan tanpa henjutan, tarikan pasangan atau sasaran sakit. SP5.1.3 digunakan mengikut ayat rasmi DSKP, bukan gabungan ayat keselamatan lama RPT.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": true, "source_code_note": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP.", "unperformed_literal_elements": ["RPT4.3.3: padanan kod unik belum disahkan; tujuan diajar melalui pernyataan4.3.2 kedua yang tercetak."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas.", "Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat.", "Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur.", "Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang.", "Tilam atau alas hanya untuk duduk. Tiada luncuran, melompat antara alas atau bantuan menarik tangan rakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Regangan betis dan belakang paha selepas gerakan ringan", "objective": "Murid dapat melakukan regangan dinamik dan statik dengan tumpuan pada posisi yang selesa.", "success_criteria": ["Melakukan dinamik lutut atau kaki serta statik betis dan belakang paha pada kedua-dua sisi.", "Mengenal jenis dan tujuan regangan serta mematuhi arahan berhenti."], "prior_knowledge": "Murid pernah mencuba gerakan kecil dan regangan statik; guru mengulang cara berhenti tanpa henjutan.", "equipment": [{"item": "Kon penanda", "quantity": "Empat kon di luar tempat pijakan.", "use": "Menandakan sempadan; bukan halangan untuk dilompat."}, {"item": "Jam guru dan buku teks", "quantity": "Satu jam; BT52–55 sebagai rujukan guru.", "use": "Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"item": "Air minuman sendiri", "quantity": "Satu botol setiap murid mengikut keperluan.", "use": "Rehat dan minum sebelum, semasa serta selepas aktiviti."}, {"item": "Tilam atau alas senaman rata", "quantity": "Satu tempat duduk setiap pasangan.", "use": "Seorang membuat regangan duduk sementara pasangan menunggu di sisi. Alas tidak berada dalam laluan berjalan."}], "preparation": ["Letak alas duduk di luar ruang berjalan dan semak tidak bergerak atau terlipat.", "Pilih dinamik fleksi lutut serta gerakan kaki rendah yang sudah diajar.", "Contoh statik belakang paha: duduk satu kaki dilunjur selesa, kaki satu lagi dibengkokkan; condong sedikit dari pinggul dengan belakang panjang, tidak perlu mencapai jari kaki. Guru menyemak kesediaan sebelum murid mencuba."], "organisation": ["Semasa dinamik, semua berada di ruang sendiri. Semasa regangan duduk, A menggunakan alas dahulu sementara B berdiri atau duduk rehat di sisi; kemudian bertukar.", "Setiap murid melakukan statik betis dan belakang paha kiri/kanan serta dinamik yang sama. Bukan satu anggota bagi satu pasangan.", "Guru memberi rehat atau julat lebih kecil. Tiada murid menarik tangan atau menekan belakang pasangannya."], "movement_cues": ["Dinamik: bengkok dan luruskan lutut sedikit; gerakkan kaki rendah atau sentuh lantai ke depan dan belakang.", "Statik betis: satu kaki ke belakang, tumit di lantai, lutut depan sedikit bengkok; tukar sisi.", "Statik belakang paha: duduk selesa, satu kaki ke depan dan lutut boleh sedikit dibengkokkan. Condong kecil dari pinggul, tangan rehat di paha; tidak perlu menyentuh kaki.", "Tahan selesa sekitar 10 saat jika mampu, lepaskan perlahan dan tukar kaki. Elakkan menghenjut atau menahan nafas.", "Kenal dinamik bergerak dan statik ditahan. Tujuannya membantu kelenturan, bukan menjamin sakit hilang atau menguji siapa paling jauh menjangkau."], "timing_note": "Statik dipraktikkan dalam giliran dengan rehat; empat ulangan dinamik dan tahan sekitar 10 saat ialah cadangan guru sahaja. Semua termasuk 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Tidak perlu sampai ke jari kaki. Condong sedikit sahaja dan beritahu jika sakit.", "pupils_do": "Murid membuat regangan belakang paha dengan lutut selesa dan tangan pada paha.", "teacher_checks": "Guru semak tiada paksaan menjangkau atau tekanan daripada pasangan."}, "bbm": ["Kon penanda — Empat kon di luar tempat pijakan.", "Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru.", "Air minuman sendiri — Satu botol setiap murid mengikut keperluan.", "Tilam atau alas senaman rata — Satu tempat duduk setiap pasangan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam guru dan buku teks", "Air minuman sendiri", "Tilam atau alas senaman rata"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk dinamik dan dua statik", "minutes": 4, "teacher": ["Guru menunjukkan dinamik lutut atau kaki rendah di ruang berdiri.", "Guru menunjukkan statik betis serta duduk belakang paha dengan tangan pada paha dan julat kecil."], "pupils": ["Murid memerhati posisi selesa dan arah kaki.", "Murid menyebut mana satu bergerak dan mana satu ditahan."], "check": "Jenis regangan dikenal; fokus statik tidak menggugurkan dinamik.", "resources": ["Ruang sendiri", "Alas"]}, {"name": "Bergerak, rehat dan tahan selesa", "minutes": 9, "teacher": ["Gunakan dua minit untuk dinamik lutut dan kaki rendah.", "Beri satu minit rehat/minum, kemudian dua minit statik betis kiri/kanan.", "Gunakan empat minit untuk regangan duduk belakang paha: dua minit setiap giliran A dan B, termasuk tukar sisi serta rehat."], "pupils": ["Murid melakukan dinamik dengan jarak selamat.", "Murid menahan statik betis pada dua sisi.", "Murid menggunakan alas pada gilirannya untuk statik belakang paha, kemudian memberi ruang pasangan."], "check": "Dua jenis dan dua sisi diperhatikan mengikut murid, tanpa ukuran jangkauan.", "resources": ["Alas", "Jam", "Air sendiri"]}, {"name": "Semak cara dan tujuan", "minutes": 7, "teacher": ["Beri dua minit kepada A dan dua minit kepada B untuk menunjukkan dinamik dan satu statik pilihan guru.", "Gunakan satu minit rehat serta dua minit menyoal jenis, tujuan dan arahan berhenti.", "Semak murid yang menggunakan julat kecil; bantuan bukan kesalahan."], "pupils": ["Murid menunjukkan gerakan serta tahan sendiri.", "Murid menamakan dinamik/statik dan menyebut tujuan membantu kelenturan.", "Murid berhenti serta meminta bantuan jika tidak selesa."], "check": "Dua pernyataan 4.3.2 dan arahan keselamatan dinilai berasingan.", "resources": ["Alas", "Ruang sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Melakukan dinamik rendah serta statik betis dan belakang paha dengan bantuan lisan.", "materials": ["Alas rata", "Ruang sendiri"], "teacher": ["Guru membenarkan lutut sedikit dibengkokkan semasa duduk.", "Beri contoh kecil dan arah satu langkah; jangan menolak badan murid."], "pupil_steps": ["Bengkok/luruskan lutut sedikit dan buat gerakan kaki rendah sebagai dinamik.", "Tahan statik betis kiri dan kanan dengan guru menunjukkan tumit.", "Duduk pada alas dan lakukan statik belakang paha kedua-dua sisi dalam julat kecil.", "Kenal dinamik/statik, sebut tujuan dan berhenti apabila diarahkan."], "product": "Dinamik serta dua statik individu dengan kata bantu.", "criterion": "Kedua-dua jenis dicuba tanpa sakit; bantuan dan bahagian belum dibuat dicatat.", "next_step": "Ulang posisi duduk yang selesa sebelum sebarang condongan.", "example": {"teacher": "Perlu sentuh jari kaki?", "pupil": "Tidak. Buat setakat selesa."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Menukar dinamik kepada statik betis dan belakang paha secara terkawal.", "materials": ["Alas pasangan", "Jam guru"], "teacher": ["Semak kedua-dua sisi dan giliran alas.", "Tanya tujuan selepas murid berhenti, bukan ketika menahan regangan."], "pupil_steps": ["Lakukan dinamik lutut/kaki dengan nafas biasa.", "Tahan statik betis dan tukar kaki.", "Lakukan statik belakang paha duduk di alas pada kedua-dua sisi.", "Sebut jenis dan tujuan serta ikut arahan keluar dari alas."], "product": "Urutan dua jenis dan penerangan individu.", "criterion": "Murid mengekalkan posisi selesa tanpa henjutan atau bantuan tarikan.", "next_step": "Perkemas satu posisi tumit atau duduk dengan contoh semula.", "example": {"teacher": "Apakah tujuan regangan ini?", "pupil": "Membantu kelenturan supaya mudah bergerak."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas pelepasan daripada statik selepas dinamik.", "materials": ["Alas rata"], "teacher": ["Minta murid melepaskan posisi perlahan sebelum tukar kaki.", "Jangan tambah masa tahan atau jarak jangkauan."], "pupil_steps": ["Lakukan dinamik rendah dan berhenti stabil.", "Tahan statik betis kiri/kanan, kemudian lepaskan perlahan.", "Lakukan statik belakang paha kiri/kanan dengan tangan di paha.", "Nyatakan dinamik/statik, tujuan dan satu cara berhenti selamat."], "product": "Dua jenis dengan pelepasan posisi yang terkawal.", "criterion": "Kawalan diperbaik, bukan julat; tujuan disebut dan arahan dipatuhi.", "next_step": "Kekalkan petunjuk lepaskan perlahan pada latihan susulan.", "example": {"teacher": "Apa dibuat sebelum tukar kaki?", "pupil": "Lepaskan regangan perlahan dahulu."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan regangan dinamik dan statik dengan tumpuan pada posisi yang selesa.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu posisi duduk Peneroka.", "Semak dua sisi Pembina.", "Perhatikan pelepasan Pencabar."], "individual_check": "Melakukan dinamik lutut atau kaki serta statik betis dan belakang paha pada kedua-dua sisi.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu semasa latihan dan giliran pasangan.", "evidence": "Lakuan dinamik dan statik lutut, betis dan belakang paha murid sendiri.", "criterion": "Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik: ____", "Statik: ____", "Kiri/kanan jika berkaitan: ____", "Bantuan / belum diperhatikan: ____"]}, "pbd_complementary": {"4.3.1": {"method": "Pemerhatian dan soalan ringkas tentang teknik.", "evidence": "Murid menunjukkan satu cara selamat ketika lutut, betis dan belakang paha.", "criterion": "Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Cara selamat ditunjukkan: ____", "Bantuan / belum dilihat: ____"]}, "PJ1-DSKP-P82-L16": {"method": "Soal jawab individu selepas bergerak.", "evidence": "Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan.", "criterion": "Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik dikenal: ____", "Statik dikenal: ____", "Bantuan: ____"]}, "PJ1-DSKP-P82-L18": {"method": "Soalan tujuan dengan kata mudah.", "evidence": "Murid menyebut tujuan regangan bagi lutut, betis dan belakang paha.", "criterion": "Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tujuan yang disebut: ____", "Kata bantu / belum didengar: ____"]}, "5.1.3": {"method": "Pemerhatian dan respons individu sepanjang latihan.", "evidence": "Tindakan mula, berhenti dan menjaga ruang mengikut arahan.", "criterion": "Arahan dipatuhi dengan bantuan; berhenti kerana sakit ialah tindakan selamat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons atau tindakan sebenar: ____", "Bantuan / rehat / belum dilihat: ____"]}}, "intervention": ["Gunakan duduk tegak dengan lutut selesa jika condongan belum sesuai.", "Bahagian yang belum dilakukan direkod dan disusuli, bukan menuntut jangkauan untuk lulus."], "book_pages_text": "52, 53, 54, 55", "sp_focus": "", "sp_display": "3.3.1", "complementary": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "0fd4eb3829d40f1dfb8bca1fd8b08e7dafb791c95ed139f5443b6b84fbc3c6e9"}'::jsonb,'[{"kind": "title", "text": "Minggu 36 Sesi 1 — Regangan betis dan belakang paha selepas gerakan ringan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W36-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Tenang-tenang"}, {"kind": "p", "text": "Aktiviti guru: Regangan betis dan belakang paha selepas gerakan ringan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 52, 53, 54, 55."}, {"kind": "p", "text": "Statik dipraktikkan dalam giliran dengan rehat; empat ulangan dinamik dan tahan sekitar 10 saat ialah cadangan guru sahaja. Semua termasuk 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.3: Melakukan senaman kelenturan dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.3.1: Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.1: Mengenal pasti cara regangan yang betul."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Menyatakan tujuan melakukan senaman regangan."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan regangan dinamik dan statik dengan tumpuan pada posisi yang selesa."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan dinamik lutut atau kaki serta statik betis dan belakang paha pada kedua-dua sisi."}, {"kind": "p", "text": "2. Mengenal jenis dan tujuan regangan serta mematuhi arahan berhenti."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah mencuba gerakan kecil dan regangan statik; guru mengulang cara berhenti tanpa henjutan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan sempadan; bukan halangan untuk dilompat."}, {"kind": "label", "text": "Jam guru dan buku teks"}, {"kind": "p", "text": "Keperluan: Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "Kegunaan: Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Rehat dan minum sebelum, semasa serta selepas aktiviti."}, {"kind": "label", "text": "Tilam atau alas senaman rata"}, {"kind": "p", "text": "Keperluan: Satu tempat duduk setiap pasangan."}, {"kind": "p", "text": "Kegunaan: Seorang membuat regangan duduk sementara pasangan menunggu di sisi. Alas tidak berada dalam laluan berjalan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Letak alas duduk di luar ruang berjalan dan semak tidak bergerak atau terlipat."}, {"kind": "p", "text": "2. Pilih dinamik fleksi lutut serta gerakan kaki rendah yang sudah diajar."}, {"kind": "p", "text": "3. Contoh statik belakang paha: duduk satu kaki dilunjur selesa, kaki satu lagi dibengkokkan; condong sedikit dari pinggul dengan belakang panjang, tidak perlu mencapai jari kaki. Guru menyemak kesediaan sebelum murid mencuba."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Semasa dinamik, semua berada di ruang sendiri. Semasa regangan duduk, A menggunakan alas dahulu sementara B berdiri atau duduk rehat di sisi; kemudian bertukar."}, {"kind": "p", "text": "2. Setiap murid melakukan statik betis dan belakang paha kiri/kanan serta dinamik yang sama. Bukan satu anggota bagi satu pasangan."}, {"kind": "p", "text": "3. Guru memberi rehat atau julat lebih kecil. Tiada murid menarik tangan atau menekan belakang pasangannya."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Dinamik: bengkok dan luruskan lutut sedikit; gerakkan kaki rendah atau sentuh lantai ke depan dan belakang."}, {"kind": "p", "text": "2. Statik betis: satu kaki ke belakang, tumit di lantai, lutut depan sedikit bengkok; tukar sisi."}, {"kind": "p", "text": "3. Statik belakang paha: duduk selesa, satu kaki ke depan dan lutut boleh sedikit dibengkokkan. Condong kecil dari pinggul, tangan rehat di paha; tidak perlu menyentuh kaki."}, {"kind": "p", "text": "4. Tahan selesa sekitar 10 saat jika mampu, lepaskan perlahan dan tukar kaki. Elakkan menghenjut atau menahan nafas."}, {"kind": "p", "text": "5. Kenal dinamik bergerak dan statik ditahan. Tujuannya membantu kelenturan, bukan menjamin sakit hilang atau menguji siapa paling jauh menjangkau."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "2. Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Tilam atau alas senaman rata — Satu tempat duduk setiap pasangan."}, {"kind": "p", "text": "5. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas."}, {"kind": "p", "text": "5. Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat."}, {"kind": "p", "text": "6. Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur."}, {"kind": "p", "text": "7. Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."}, {"kind": "p", "text": "8. Tilam atau alas hanya untuk duduk. Tiada luncuran, melompat antara alas atau bantuan menarik tangan rakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam guru dan buku teks Air minuman sendiri Tilam atau alas senaman rata"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk dinamik dan dua statik — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan dinamik lutut atau kaki rendah di ruang berdiri."}, {"kind": "p", "text": "2. Guru menunjukkan statik betis serta duduk belakang paha dengan tangan pada paha dan julat kecil."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memerhati posisi selesa dan arah kaki."}, {"kind": "p", "text": "2. Murid menyebut mana satu bergerak dan mana satu ditahan."}, {"kind": "p", "text": "Semakan: Jenis regangan dikenal; fokus statik tidak menggugurkan dinamik."}, {"kind": "p", "text": "Alatan: Ruang sendiri Alas"}, {"kind": "h3", "text": "Langkah 4: Bergerak, rehat dan tahan selesa — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan dua minit untuk dinamik lutut dan kaki rendah."}, {"kind": "p", "text": "2. Beri satu minit rehat/minum, kemudian dua minit statik betis kiri/kanan."}, {"kind": "p", "text": "3. Gunakan empat minit untuk regangan duduk belakang paha: dua minit setiap giliran A dan B, termasuk tukar sisi serta rehat."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan dinamik dengan jarak selamat."}, {"kind": "p", "text": "2. Murid menahan statik betis pada dua sisi."}, {"kind": "p", "text": "3. Murid menggunakan alas pada gilirannya untuk statik belakang paha, kemudian memberi ruang pasangan."}, {"kind": "p", "text": "Semakan: Dua jenis dan dua sisi diperhatikan mengikut murid, tanpa ukuran jangkauan."}, {"kind": "p", "text": "Alatan: Alas Jam Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Semak cara dan tujuan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit kepada A dan dua minit kepada B untuk menunjukkan dinamik dan satu statik pilihan guru."}, {"kind": "p", "text": "2. Gunakan satu minit rehat serta dua minit menyoal jenis, tujuan dan arahan berhenti."}, {"kind": "p", "text": "3. Semak murid yang menggunakan julat kecil; bantuan bukan kesalahan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjukkan gerakan serta tahan sendiri."}, {"kind": "p", "text": "2. Murid menamakan dinamik/statik dan menyebut tujuan membantu kelenturan."}, {"kind": "p", "text": "3. Murid berhenti serta meminta bantuan jika tidak selesa."}, {"kind": "p", "text": "Semakan: Dua pernyataan 4.3.2 dan arahan keselamatan dinilai berasingan."}, {"kind": "p", "text": "Alatan: Alas Ruang sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Tidak perlu sampai ke jari kaki. Condong sedikit sahaja dan beritahu jika sakit."}, {"kind": "p", "text": "Murid: Murid membuat regangan belakang paha dengan lutut selesa dan tangan pada paha."}, {"kind": "p", "text": "Semakan guru: Guru semak tiada paksaan menjangkau atau tekanan daripada pasangan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W36-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan regangan dinamik dan statik dengan tumpuan pada posisi yang selesa."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu posisi duduk Peneroka."}, {"kind": "p", "text": "2. Semak dua sisi Pembina."}, {"kind": "p", "text": "3. Perhatikan pelepasan Pencabar."}, {"kind": "p", "text": "Semakan individu: Melakukan dinamik lutut atau kaki serta statik betis dan belakang paha pada kedua-dua sisi."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Melakukan dinamik rendah serta statik betis dan belakang paha dengan bantuan lisan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alas rata"}, {"kind": "p", "text": "2. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru membenarkan lutut sedikit dibengkokkan semasa duduk."}, {"kind": "p", "text": "2. Beri contoh kecil dan arah satu langkah; jangan menolak badan murid."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bengkok/luruskan lutut sedikit dan buat gerakan kaki rendah sebagai dinamik."}, {"kind": "p", "text": "2. Tahan statik betis kiri dan kanan dengan guru menunjukkan tumit."}, {"kind": "p", "text": "3. Duduk pada alas dan lakukan statik belakang paha kedua-dua sisi dalam julat kecil."}, {"kind": "p", "text": "4. Kenal dinamik/statik, sebut tujuan dan berhenti apabila diarahkan."}, {"kind": "p", "text": "Contoh guru: Perlu sentuh jari kaki?"}, {"kind": "p", "text": "Contoh respons murid: Tidak. Buat setakat selesa."}, {"kind": "p", "text": "Hasil individu: Dinamik serta dua statik individu dengan kata bantu."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dicuba tanpa sakit; bantuan dan bahagian belum dibuat dicatat."}, {"kind": "p", "text": "Susulan: Ulang posisi duduk yang selesa sebelum sebarang condongan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Menukar dinamik kepada statik betis dan belakang paha secara terkawal."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alas pasangan"}, {"kind": "p", "text": "2. Jam guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak kedua-dua sisi dan giliran alas."}, {"kind": "p", "text": "2. Tanya tujuan selepas murid berhenti, bukan ketika menahan regangan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dinamik lutut/kaki dengan nafas biasa."}, {"kind": "p", "text": "2. Tahan statik betis dan tukar kaki."}, {"kind": "p", "text": "3. Lakukan statik belakang paha duduk di alas pada kedua-dua sisi."}, {"kind": "p", "text": "4. Sebut jenis dan tujuan serta ikut arahan keluar dari alas."}, {"kind": "p", "text": "Contoh guru: Apakah tujuan regangan ini?"}, {"kind": "p", "text": "Contoh respons murid: Membantu kelenturan supaya mudah bergerak."}, {"kind": "p", "text": "Hasil individu: Urutan dua jenis dan penerangan individu."}, {"kind": "p", "text": "Kriteria: Murid mengekalkan posisi selesa tanpa henjutan atau bantuan tarikan."}, {"kind": "p", "text": "Susulan: Perkemas satu posisi tumit atau duduk dengan contoh semula."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas pelepasan daripada statik selepas dinamik."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alas rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minta murid melepaskan posisi perlahan sebelum tukar kaki."}, {"kind": "p", "text": "2. Jangan tambah masa tahan atau jarak jangkauan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dinamik rendah dan berhenti stabil."}, {"kind": "p", "text": "2. Tahan statik betis kiri/kanan, kemudian lepaskan perlahan."}, {"kind": "p", "text": "3. Lakukan statik belakang paha kiri/kanan dengan tangan di paha."}, {"kind": "p", "text": "4. Nyatakan dinamik/statik, tujuan dan satu cara berhenti selamat."}, {"kind": "p", "text": "Contoh guru: Apa dibuat sebelum tukar kaki?"}, {"kind": "p", "text": "Contoh respons murid: Lepaskan regangan perlahan dahulu."}, {"kind": "p", "text": "Hasil individu: Dua jenis dengan pelepasan posisi yang terkawal."}, {"kind": "p", "text": "Kriteria: Kawalan diperbaik, bukan julat; tujuan disebut dan arahan dipatuhi."}, {"kind": "p", "text": "Susulan: Kekalkan petunjuk lepaskan perlahan pada latihan susulan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu semasa latihan dan giliran pasangan."}, {"kind": "p", "text": "Bukti: Lakuan dinamik dan statik lutut, betis dan belakang paha murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik: ____"}, {"kind": "p", "text": "2. Statik: ____"}, {"kind": "p", "text": "3. Kiri/kanan jika berkaitan: ____"}, {"kind": "p", "text": "4. Bantuan / belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan soalan ringkas tentang teknik."}, {"kind": "p", "text": "Bukti: Murid menunjukkan satu cara selamat ketika lutut, betis dan belakang paha."}, {"kind": "p", "text": "Kriteria: Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Cara selamat ditunjukkan: ____"}, {"kind": "p", "text": "2. Bantuan / belum dilihat: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas bergerak."}, {"kind": "p", "text": "Bukti: Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik dikenal: ____"}, {"kind": "p", "text": "2. Statik dikenal: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "Kaedah: Soalan tujuan dengan kata mudah."}, {"kind": "p", "text": "Bukti: Murid menyebut tujuan regangan bagi lutut, betis dan belakang paha."}, {"kind": "p", "text": "Kriteria: Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tujuan yang disebut: ____"}, {"kind": "p", "text": "2. Kata bantu / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan respons individu sepanjang latihan."}, {"kind": "p", "text": "Bukti: Tindakan mula, berhenti dan menjaga ruang mengikut arahan."}, {"kind": "p", "text": "Kriteria: Arahan dipatuhi dengan bantuan; berhenti kerana sakit ialah tindakan selamat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons atau tindakan sebenar: ____"}, {"kind": "p", "text": "2. Bantuan / rehat / belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Gunakan duduk tegak dengan lutut selesa jika condongan belum sesuai."}, {"kind": "p", "text": "2. Bahagian yang belum dilakukan direkod dan disusuli, bukan menuntut jangkauan untuk lulus."}]'::jsonb,'{"source_hold": "", "adaptation_note": "RPT menumpukan statik BT54–55; dinamik BT52–53 digunakan dalam sesi juga. Dua pernyataan 4.3.2 tercetak dikekalkan; nombor RPT4.3.3 ditanda konflik. Regangan lembut kiri/kanan tanpa henjutan, tarikan pasangan atau sasaran sakit. SP5.1.3 digunakan mengikut ayat rasmi DSKP, bukan gabungan ayat keselamatan lama RPT.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb)
